        },
        "2d2f3b53-c544-4823-a65f-da53ff8f594e": {
          "name": "CLOCKWORK SPIDER",
          "version": "1.0",
          "description": "Opportunistic actor that installs custom root certificate on victim to support man-in-the-middle network monitoring.",
          "icon": "",
