        "e665ac2f-87b4-4c2e-bef7-78bf0a8af87b": {
          "name": "Predatory Sparrow",
          "version": "1.0",
          "description": "A self-proclaimed hacktivist group that carried out attacks against Iranian railway systems and against Iranian steel plants.",
