        "1c047671-227b-466f-9929-37df40abd485": {
          "name": "The Gentlemen",
          "version": "1.1",
          "description": "The Gentlemen is a ransomware group that employs a dual-extortion strategy, encrypting sensitive files while exfiltrating critical business data to pressure victims into paying ransoms. Their operations leverage advanced techniques such as abusing legitimate utilities like PowerRun.exe for privilege escalation, using custom-built tools for defense evasion, and employing flexible encryption methods based on file size. The group targets medium to large organizations across various sectors, particularly in the Asia-Pacific region, and has demonstrated a high level of technical maturity and operational discipline. Their activities include systematic compromise of enterprise environments, mass account enumeration, and the use of encrypted channels for data exfiltration.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "1c047671-227b-466f-9929-37df40abd485"
        },
        "a8386969-bf32-47f7-b460-78e0d0a9ef38": {
          "name": "UNC6201",
          "version": "1.1",
          "description": "UNC6201 is a sophisticated Chinese state-sponsored hacking group that exploited CVE-2026–22769, a critical vulnerability in Dell RecoverPoint for Virtual Machines appliances, to establish a persistent presence. They deployed a permanent backdoor using techniques like Single Packet Authorization and \"Port Knocking.\" Unlike typical hackers who conceal their activities within the Operating System, UNC6201 operated at the Virtualization Layer to avoid detection.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "a8386969-bf32-47f7-b460-78e0d0a9ef38"
        },
        "18d4647b-2be2-4c50-87dc-8fdcec4d2664": {
          "name": "UNC2814",
          "version": "1.1",
          "description": "UNC2814 is a suspected PRC-nexus cyber espionage group that has targeted telecommunications providers and government entities globally since at least 2017. The group employs the GRIDTIDE backdoor to blend malicious traffic with legitimate cloud API activity and utilizes living-off-the-land techniques, including SSH lateral movement and the creation of malicious systemd services. GTIG has confirmed 53 intrusions across 42 countries and identified suspected activity in at least 20 additional nations, with a focus on exfiltrating sensitive communications data. Google has taken significant disruption actions against UNC2814, including infrastructure takedowns and the release of IOCs to aid in detection.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "18d4647b-2be2-4c50-87dc-8fdcec4d2664",
          "alias": [
            "DARK CASTLE"
          ]
        },
        "65e448d3-aff5-4fb4-9aec-d73daabd1aad": {
          "name": "ChainedShark",
          "version": "1.1",
          "description": "ChainedShark is an APT group targeting China's scientific research sector, particularly professionals in international relations and marine technology, with the intent to steal sensitive data. The group employs advanced techniques, including executable file reconstruction to create fragmented shellcode, and utilizes social engineering tactics to exploit professional scenarios for deceptive attacks. ChainedShark demonstrates a high level of technical sophistication, integrating N-day vulnerability exploits and custom trojans within meticulously designed attack chains. Its operations reflect a mature attack infrastructure and a clear evolutionary trajectory in tactics and execution.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "65e448d3-aff5-4fb4-9aec-d73daabd1aad",
          "alias": [
            "Actor240820"
          ]
        },
        "1dc3ec7d-32f6-43f1-8686-c35c44b9a83d": {
          "name": "GrayBravo",
          "version": "1.1",
          "description": "TAG-150, also known as GrayBravo, is a sophisticated threat actor responsible for developing multiple custom malware families, including CastleLoader and CastleRAT, and operates a large-scale, multi-layered infrastructure. The group employs the ClickFix technique to distribute malware through phishing attacks that impersonate legitimate services, leveraging deceptive domains and fake repositories. Insikt Group has identified four distinct activity clusters associated with TAG-150, each targeting different victim profiles and utilizing unique TTPs.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "1dc3ec7d-32f6-43f1-8686-c35c44b9a83d",
          "alias": [
            "TAG-150"
          ]
        },
        "9b3df41b-4078-4f83-92df-d7d132c619cd": {
          "name": "Water Kurita",
          "version": "1.1",
          "description": "Water Kurita is a financially motivated cybercriminal entity associated with the Lumma Stealer infostealer-as-a-service operation, primarily active on underground forums and marketplaces. It focuses on credential and information theft at scale, monetizing access via subscription-based malware distribution and resale of stolen data to other actors. The group demonstrates solid operational security and marketing tactics typical of mature MaaS ecosystems, although a 2025 doxxing campaign exposing alleged core members (personal and financial data) significantly disrupted its activity and drove customers toward competing infostealers.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "9b3df41b-4078-4f83-92df-d7d132c619cd"
        },
        "c368d31a-8fd1-4d51-8fc4-9ea597bfe5b5": {
          "name": "UAT-8616",
          "version": "1.1",
          "description": "UAT-8616 is a highly sophisticated cyber threat actor attributed by Cisco Talos, with evidence of activity dating back to at least 2023. They have been observed exploiting CVE-2026-20127 in the wild and previously exploited CVE-2022-20775 by escalating to root user access through a software version downgrade. Their operations indicate a focus on targeting network edge devices to establish persistent footholds in high-value organizations, including Critical Infrastructure sectors.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "c368d31a-8fd1-4d51-8fc4-9ea597bfe5b5"
        },
        "05f4caf3-87cf-43e3-87ba-cc854578dc7d": {
          "name": "UAT-9244",
          "version": "1.1",
          "description": "UAT-9244 is a China-nexus APT actor, disclosed by Cisco Talos on March 5, 2026, assessed with high confidence as closely associated with Famous Sparrow and overlapping with Tropic Trooper. Active since 2024, it exclusively targets South American telecommunication providers, deploying three novel cross-platform malware families: TernDoor (Windows backdoor with DLL side-loading and evasion driver), PeerTime (Linux/embedded backdoor using BitTorrent for resilient C2), and BruteEntry (GoLang scanner turning edge devices into Operational Relay Boxes for SSH/Postgres/Tomcat brute-force). The campaign enables persistent access, remote command execution, lateral movement, and infrastructure relay via unified C2 with shared SSL certificates and domains like bloopencil.net.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "05f4caf3-87cf-43e3-87ba-cc854578dc7d"
        },
        "1ffa7788-5507-4a6f-a415-30508ee010a2": {
          "name": "GTFire",
          "version": "1.1",
          "description": "GTFire is a threat actor that leverages Google Firebase for hosting phishing pages and Google Translate to disguise malicious URLs, effectively bypassing security filters. The campaign employs a multi-step redirect chain to obscure the final phishing destination and utilizes All-in-1 PHP phishing scripts for rapid deployment and credential harvesting. Credentials are exfiltrated via URL parameters in a standard HTTP GET request, with minimal operational overhead.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "1ffa7788-5507-4a6f-a415-30508ee010a2"
        },
        "266af6b4-1f11-4043-9de1-90527406f406": {
          "name": "NetRunnerPR",
          "version": "1.1",
          "description": "NetRunnerPR has claimed to breach the networks of Shiraume Hospital and Nippon Medical School Musashi Kosugi Hospital in Japan, exfiltrating patient PII and medical records. The actor announced plans to release a complete database on March 5, 2026, and an additional 20,000 records on February 16, 2026, contingent on undisclosed conditions. The claims were made on a cybercrime forum, accompanied by sample data to validate the breaches. NetRunnerPR's account shows limited activity history and lacks a documented history of major ransomware operations or confirmed breaches, raising questions about the credibility of the claims.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "266af6b4-1f11-4043-9de1-90527406f406"
        },
        "b2765bd8-1200-4df5-a9d3-72a7b679dcdb": {
          "name": "Contagious Interview",
          "version": "1.1",
          "description": "Contagious Interview is a North Korea–aligned threat group active since 2023. The group conducts both cyberespionage and financially motivated operations, including the theft of cryptocurrency and user credentials. Contagious Interview targets Windows, Linux, and macOS systems, with a particular focus on individuals engaged in software development and cryptocurrency-related activities.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "b2765bd8-1200-4df5-a9d3-72a7b679dcdb"
        },
        "8d8cbe24-0552-421e-9a3f-42bd2b6c8824": {
          "name": "CL-STA-1087",
          "version": "1.1",
          "description": "CL-STA-1087 is a suspected state-sponsored espionage campaign operating out of China, targeting military organizations in Southeast Asia. The actor has demonstrated operational patience, maintaining dormant access for extended periods while focusing on precision intelligence collection and employing robust operational security measures. Their infrastructure includes the use of a legitimate cloud service for C2 operations, indicating a cloud-native approach. File timestamps and other indicators trace the campaign's activity back to 2020, suggesting a long-running operation.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "8d8cbe24-0552-421e-9a3f-42bd2b6c8824"
        },
        "1515f68c-5b42-479a-bb38-adcb6f11e8af": {
          "name": "UNC6426",
          "version": "1.1",
          "description": "UNC6426 exploited a supply chain compromise of the nx npm package to steal a developer's GitHub Personal Access Token and gain access to a victim's cloud environment. They abused the GitHub-to-AWS OpenID Connect trust to create a new administrator role, leveraging overly permissive permissions associated with the compromised GitHub-Actions-CloudFormation role. Using the legitimate open-source tool Nord Stream, UNC6426 conducted reconnaissance and extracted secrets from CI/CD environments, leading to the exfiltration of files from AWS S3 buckets and data destruction. The actor escalated to full AWS administrator permissions in under 72 hours.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "1515f68c-5b42-479a-bb38-adcb6f11e8af"
        },
        "af5320b8-07a9-4703-a657-a11f728ef570": {
          "name": "Z-Pentest Alliance",
          "version": "1.1",
          "description": "Z-Pentest Alliance is a pro-Russian hacktivist group known for targeting industrial control systems and operational technology systems, particularly in Italy and Israel. The group has claimed responsibility for various attacks, including gaining control of a water supply management system and disrupting aviation authorities' websites. Z-Pentest Alliance operates within a larger alliance of hacktivist groups, often collaborating on politically motivated operations, including DDoS campaigns. The group has been linked to the GRU and is associated with the NoName057 group, sharing tools and intelligence.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "af5320b8-07a9-4703-a657-a11f728ef570",
          "alias": [
            "Z-Pentest"
          ]
        },
        "ffd700a7-c540-421f-a52a-9fd6fba8d18b": {
          "name": "313 Team",
          "version": "1.1",
          "description": "313 Team is an Iraq-based threat actor that has conducted coordinated DDoS campaigns targeting multiple government servers in the UAE, Kuwait, and Romania, often in response to political statements. They have claimed responsibility for significant disruptions, including a one-hour shutdown of Romania’s National Tax Agency and an 18-hour outage of Kuwait's national e-government portal. The group has also engaged in website defacements, showcasing coordinated branding with other aligned groups. Their operations reflect a focus on government infrastructure, employing DDoS techniques and leveraging public political discourse as justification for their attacks.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "ffd700a7-c540-421f-a52a-9fd6fba8d18b"
        },
        "7223da47-59b4-4c5c-9f97-d7ceb5866651": {
          "name": "TA2723",
          "version": "1.1",
          "description": "TA2723 is a financially-motivated, high-volume credential phishing threat actor known for spoofing Microsoft OneDrive, LinkedIn, and DocuSign. Proofpoint Threat Research has observed TA2723 conducting OAuth device code phishing campaigns, utilizing tools like Squarephish and Graphish to enhance their operations. The use of these tools allows TA2723 to mitigate the short-lived nature of device codes, facilitating larger campaigns. Successful attacks can lead to M365 account takeover, data exfiltration, and lateral movement.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "7223da47-59b4-4c5c-9f97-d7ceb5866651"
        },
        "f1622e18-f1dc-40b4-aca9-992e29b8fb40": {
          "name": "Infrastructure Destruction Squad",
          "version": "1.1",
          "description": "Dark Engine has emerged as a significant threat actor targeting industrial control systems and SCADA systems in sectors such as metallurgy and food processing. The group has conducted multiple ICS-targeted incidents, with a pronounced operational surge in June 2025. Additionally, Dark Engine is involved in a campaign that embeds fraudulent CAPTCHA prompts into legitimate WordPress sites, utilizing SEO poisoning to harvest login credentials. Reports also indicate a data leak from Dark Engine that exposed sensitive phone data in the U.S.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "f1622e18-f1dc-40b4-aca9-992e29b8fb40",
          "alias": [
            "Dark Engine"
          ]
        },
        "3eab2d9f-8258-4b2f-9bc9-4dabcabfefb0": {
          "name": "Cyber Islamic Resistance",
          "version": "1.1",
          "description": "Cyber Islamic Resistance is a hacktivist collective ideologically aligned with Iran, engaging in operations such as website defacements, DDoS attacks, and data exfiltration targeting Israeli and Western entities. They have claimed breaches of Israeli cybersecurity firms and academic platforms, framing their actions as part of a broader narrative of retaliation. The group has also targeted critical infrastructure, asserting access to industrial control systems and operational technology environments. Their activities are often presented as part of a coordinated cyber mobilization campaign, emphasizing psychological and reputational impacts.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "3eab2d9f-8258-4b2f-9bc9-4dabcabfefb0"
        },
        "20912a84-43b0-4fad-a30b-9ee3253da721": {
          "name": "Conquerors Electronic Army",
          "version": "1.1",
          "description": "Conquerors Electronic Army operates under the “Wa’d al-Akhira” banner and has claimed multiple attacks against Israeli targets, including civil emergency alerting and healthcare sectors, utilizing rented stresser infrastructure and CheckHost proof-of-disruption links. The group has embedded links to a UK-registered charity in their operations, suggesting a potential disruption attempt rather than solely an information operation. Security company Radware identified Conquerors Electronic Army as one of the primary actors behind a series of DDoS attacks targeting government entities in the Middle East. Their activities indicate a focus on both disruptive and influence operations.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "20912a84-43b0-4fad-a30b-9ee3253da721"
        },
        "c6e6d7fe-e8c3-4a33-8603-4bf44dec3b75": {
          "name": "Keymous+",
          "version": "1.1",
          "description": "Keymous is a threat actor known for executing extensive DDoS attacks across multiple Arab countries, targeting government ministries and critical infrastructure. The group has claimed access to sensitive data, including over 300,000 records from Israel's Ministry of Education, and has engaged in reconnaissance activities against various ministries in Bahrain and other nations. Keymous employs diverse infrastructure, including compromised IoT devices and DDoS-for-hire platforms, to amplify attack bandwidth. Their operations have been characterized by a focus on politically motivated cyberattacks, particularly in the context of regional conflicts.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "c6e6d7fe-e8c3-4a33-8603-4bf44dec3b75",
          "alias": [
            "keymous",
            "Keymous Plus"
          ]
        },
        "207fea73-aebd-40c0-a8de-63bb605cada2": {
          "name": "APTIran",
          "version": "1.1",
          "description": "APTIran has claimed responsibility for a large-scale campaign targeting Israeli critical infrastructure, asserting infiltration of government ministries, hospitals, universities, and financial institutions as retaliation for Israeli military operations. The group has leaked over 350,000 Israeli government login credentials and approximately 300 internal databases, while also threatening to create a 'zombie' network from infected devices. They have reportedly deployed ransomware strains such as ALPHV and LockBit as part of their offensive toolkit. Additionally, APTIran has made unverified claims of compromising Israeli water control systems and the state-owned food security agency Jordan Silos and Supply General Co.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "207fea73-aebd-40c0-a8de-63bb605cada2"
        },
        "d3682137-2845-424f-be8a-9112d23f4f58": {
          "name": "TeamPCP",
          "version": "1.1",
          "description": "TeamPCP is a threat actor that has executed a coordinated series of supply chain attacks, compromising widely-used open source tools such as Trivy, KICS, and LiteLLM to deploy credential-stealing malware. They employed techniques like credential harvesting, lateral movement within Kubernetes environments, and audio steganography to evade detection. The group has demonstrated the ability to leverage stolen credentials to propagate attacks across multiple ecosystems, including npm and PyPI, using a self-propagating worm known as CanisterWorm. Their operations have included the use of AES-256 encryption and RSA-4096 for exfiltration of sensitive data.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "d3682137-2845-424f-be8a-9112d23f4f58",
          "alias": [
            "Altered Spider",
            "PCPcat",
            "ShellForce",
            "DeadCatx3",
            "CanisterWorm"
          ]
        },
        "cab59c56-7446-4c62-bb4e-0887fca42839": {
          "name": "Larva-26002",
          "version": "1.1",
          "description": "Larva-26002 targets improperly managed MS-SQL servers, exploiting vulnerabilities such as brute force and dictionary attacks. The actor has distributed Trigona and Mimic ransomware, utilizing the Bulk Copy Program for exploitation and installing remote access tools like AnyDesk and Teramind. In their attacks, they also deploy scanner malware, including ICE Cloud Client written in Go and a Rust-based scanner. After compromising systems, they execute commands to gather information about the infected environment.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "cab59c56-7446-4c62-bb4e-0887fca42839"
        },
        "0979be99-61f3-4356-98b5-db06e24f2049": {
          "name": "Bearlyfy",
          "version": "1.1",
          "description": "Bearlyfy has been attributed to over 70 cyber attacks targeting Russian companies since its emergence in January 2025, employing a custom Windows ransomware strain known as GenieLocker. The group operates with dual objectives of extortion and sabotage, utilizing a modified version of PolyVice and leveraging vulnerabilities in external services and applications for initial access. Analysis reveals overlaps with PhantomCore, indicating a pro-Ukrainian interest, while Bearlyfy's attacks are characterized by minimal preparation and a focus on immediate impact through data encryption and destruction. Approximately 20% of victims reportedly pay the ransom, with demands escalating to hundreds of thousands of dollars.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "0979be99-61f3-4356-98b5-db06e24f2049",
          "alias": [
            "Labubu"
          ]
        },
        "88ba3275-6eda-4ff4-b54e-1be126e13bec": {
          "name": "UAT-10608",
          "version": "1.1",
          "description": "UAT-10608 is a threat cluster observed by Cisco Talos conducting a large-scale, automated credential-harvesting campaign against public-facing web applications, especially Next.js deployments, using a custom framework called NEXUS Listener to extract and exfiltrate secrets such as credentials, SSH keys, cloud tokens, and API keys. The activity has been linked to broad opportunistic scanning and at least 766 compromised hosts across multiple regions and cloud providers.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "88ba3275-6eda-4ff4-b54e-1be126e13bec"
        },
        "e6e4a9a2-e20d-4f95-8b8b-73b21a3d3fa9": {
          "name": "Mythic Likho",
          "version": "1.1",
          "description": "Arcane Werewolf has been observed targeting Russian manufacturing enterprises through phishing emails that lead to malicious links and spoofed websites. The actor has utilized ZIP archives containing malicious LNK files and a C++ dropper in their campaigns. Their infrastructure includes a C2 server disguised as a Russian manufacturing company website. Kaspersky researchers have noted their evolving TTPs, indicating either a new group or one that has significantly improved its methods.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "e6e4a9a2-e20d-4f95-8b8b-73b21a3d3fa9",
          "alias": [
            "Arcane Werewolf"
          ]
        },
        "898033a1-8e4c-400d-b4a2-c59bfc64970a": {
          "name": "Cyber Serp",
          "version": "1.1",
          "description": "UAC-0255 is a threat actor that conducted a phishing campaign impersonating CERT-UA to distribute the AGEWHEEZE RAT, targeting organizations in Ukraine's public and private sectors. The campaign is part of a broader trend of using trusted identities to enhance victim engagement, as seen in previous activities like UAC-0190 and UAC-0252. CERT-UA identified UAC-0255 after discovering links to the CyberSerp Telegram channel, which claimed responsibility for the attack. The activity is documented under the identifier CERT-UA#21075, with detection rules available for cybersecurity analysts.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "898033a1-8e4c-400d-b4a2-c59bfc64970a",
          "alias": [
            "UAC-0255"
          ]
        },
        "c2049438-940f-4961-a072-4b0981e81471": {
          "name": "RuskiNet",
          "version": "1.1",
          "description": "RuskiNet is a pro-Russian hacktivist collective associated with disruptive operations including DDoS attacks, website defacements, phishing, and data leaks against government, infrastructure, financial, and civil targets.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "c2049438-940f-4961-a072-4b0981e81471"
        },
        "bebcafbd-49ec-442f-9184-260c8c327f89": {
          "name": "Coinbase Cartel",
          "version": "1.1",
          "description": "Coinbase Cartel is a ransomware threat actor that emerged in September 2025, focusing on data exfiltration rather than encryption, and has claimed over 60 victims, primarily in the healthcare, technology, and transportation sectors. The group employs TTPs such as social engineering, credential harvesting, and collaboration with Initial Access Brokers to gain initial access. They operate a data leak site where they publish victim names and issue ransom demands, requiring payment via Bitcoin.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "bebcafbd-49ec-442f-9184-260c8c327f89"
        },
        "6ec20d92-b194-40dc-a486-af335cf85a78": {
          "name": "GrayCharlie",
          "version": "1.1",
          "description": "GrayCharlie is a threat actor that compromises WordPress sites to inject malicious JavaScript, redirecting visitors to NetSupport RAT payloads via fake browser update pages or ClickFix mechanisms. Insikt Group has identified extensive infrastructure linked to GrayCharlie, primarily associated with MivoCloud and HZ Hosting Ltd., including command-and-control servers and staging infrastructure. The group employs two primary attack chains to deliver the NetSupport RAT, utilizing both fake updates and ClickFix techniques. GrayCharlie targets organizations worldwide, with a particular focus on the US, and has shown persistent behavior in its operations since its emergence in 2023.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "6ec20d92-b194-40dc-a486-af335cf85a78"
        },
        "74015ecc-3eaa-468b-9841-927773259f94": {
          "name": "Ababil of Minab",
          "version": "1.1",
          "description": "Ababil of Minab is an emerging pro-Iranian hacktivist group with a limited public profile and little verifiable prior activity in threat intelligence reporting. The group claims responsibility for a cyberattack and allegedly possesses administrative access to targeted systems. Their pro-Iran messaging and targeting of a major US public transit authority align with known patterns of Iranian-aligned actors targeting US critical infrastructure. The use of escalatory language suggests potential for further activity.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "74015ecc-3eaa-468b-9841-927773259f94"
        },
        "d73792c0-97d3-4aff-8e34-96bf335bf54b": {
          "name": "Krybit",
          "version": "1.1",
          "description": "Krybit is a ransomware group that operates as a ransomware-as-a-service provider, offering affiliates 80% of ransom proceeds in exchange for technical support and a malware suite. The group has claimed attacks on various organizations across multiple countries, including asesoriauriel.com in Spain and fraper.com in Spain, without disclosing the volume of data exfiltrated. Krybit is currently engaged in a turf war with another group, 0APT, and has been accused of fabricating victim claims. Their leak site has been used to publish compromised data and to issue threats to rivals and victims alike.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "d73792c0-97d3-4aff-8e34-96bf335bf54b"
        },
        "cdacd83a-d89e-4101-b1ae-f5da5041eba1": {
          "name": "CashRewindo",
          "version": "1.1",
          "description": "CashRewindo is a sophisticated threat actor leveraging aged domains in global malvertising campaigns to direct victims to investment scam sites. The group employs TTPs such as flipping between scam ads and innocuous content, as well as A/B testing to exploit time-based creative verification systems. Their operations are characterized by tailored campaigns that utilize localized language and imagery across diverse regions, including Europe, Asia, Africa, and the Americas. Additionally, CashRewindo smuggles malicious code within common JavaScript libraries to enhance their effectiveness.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "cdacd83a-d89e-4101-b1ae-f5da5041eba1"
        },
        "367a3c6c-8291-4428-8670-da0f9a59300e": {
          "name": "UAT-10362",
          "version": "1.1",
          "description": "UAT-10362 is a threat actor identified by Cisco Talos, conducting spear-phishing campaigns targeting Taiwanese NGOs and suspected universities to deploy the malware \"LucidRook.\" The malware features a multi-language modular design, layered anti-analysis capabilities, and stealth-focused payload handling. UAT-10362's operations rely on compromised or public infrastructure, indicating a mature level of operational tradecraft.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "367a3c6c-8291-4428-8670-da0f9a59300e"
        },
        "f5d231d4-8590-4770-b511-e7a44dce59f7": {
          "name": "SHADOW-AETHER-015",
          "version": "1.1",
          "description": "SHADOW-AETHER-015 is a highly adaptable cybercriminal group known for identity abuse and cloud compromise, primarily targeting identity and access management systems like Okta and Azure AD/Entra ID. They employ sophisticated social engineering techniques, including vishing and help-desk impersonation, to gain access to legitimate credentials. Their operations involve multi-pressure extortion tactics, such as data theft, ransomware, and employee intimidation, while leveraging MFA fatigue and token theft to bypass authentication controls. The group has been linked to the \"0ktapus\" phishing campaign and is most active in English-speaking countries, with a focus on sectors rich in sensitive data.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "f5d231d4-8590-4770-b511-e7a44dce59f7"
        },
        "d35a871f-402b-4a0e-a702-04e886abe883": {
          "name": "GopherWhisper",
          "version": "1.1",
          "description": "GopherWhisper is a China-aligned APT that routes C2 traffic through legitimate enterprise platforms like Slack, Discord, and Microsoft 365 Outlook to evade detection. Its toolkit includes the LaxGopher backdoor for Slack, RatGopher for Discord, and CompactGopher for data exfiltration via file.io. The group employs DLL side-loading via JabGopher and uses raw OpenSSL socket C2 on port 443 with the SSLORDoor backdoor. GopherWhisper has targeted Mongolian government entities and is assessed to have additional unidentified victims in Central Asia.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "d35a871f-402b-4a0e-a702-04e886abe883"
        },
        "75714cef-0265-4944-84c6-f66aec01994d": {
          "name": "HexagonalRodent",
          "version": "1.1",
          "description": "HexagonalRodent targets Web3 developers to steal crypto assets, employing social engineering tactics such as fake job offers. They utilize malware like BeaverTail and OtterCookie, both NodeJS-based toolkits, and InvisibleFerret, a Python-based RAT, to execute their attacks. Their TTPs include backdooring skills assessments via VSCode's tasks.json feature and conducting opportunistic exfiltration of credentials and crypto wallets. The group has also engaged in a supply chain attack, compromising the 'fast-draft' VSX extension to install malware.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "75714cef-0265-4944-84c6-f66aec01994d"
        },
        "317ecce2-5e79-4453-b6d3-727d7fe8eb4f": {
          "name": "UNC6692",
          "version": "1.1",
          "description": "UNC6692 is a threat actor that employs social engineering tactics, such as impersonating IT helpdesk personnel, to gain initial access to victim environments. They utilize a custom modular malware suite, including components like SNOWBELT, SNOWGLAZE, and SNOWBASIN, to facilitate deep network penetration and lateral movement. After extracting credentials from the LSASS process memory, they leverage Pass-The-Hash techniques to authenticate to domain controllers and exfiltrate sensitive data using LimeWire. The campaign highlights the systematic abuse of legitimate cloud services for payload delivery and command-and-control infrastructure.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "317ecce2-5e79-4453-b6d3-727d7fe8eb4f"
        },
        "2a105c46-90b1-4cff-9f66-464f8c66c22f": {
          "name": "Nickel Alley",
          "version": "1.1",
          "description": "NICKEL ALLEY is a North Korean threat group that targets technology professionals through fake job opportunities, employing social engineering tactics such as creating fraudulent LinkedIn pages and GitHub repositories for malware delivery. They utilize the ClickFix tactic to deploy the PyLangGhost RAT, which supports file exfiltration and system profiling, particularly focusing on Chrome cryptocurrency wallet data. The group has also leveraged Visual Studio Code tasks to execute commands for malware retrieval based on the victim's operating system. Their operations indicate a dual focus on cryptocurrency theft and potential supply chain compromise or corporate espionage.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "2a105c46-90b1-4cff-9f66-464f8c66c22f"
        },
        "34f06d4a-8497-40ab-8614-bba6fd4754a3": {
          "name": "UAT-8302",
          "version": "1.1",
          "description": "UAT-8302 is a sophisticated China-nexus APT group targeting government entities in South America and southeastern Europe, deploying custom-made malware such as NetDraft, CloudSorcerer version 3, and VSHELL. They utilize tools like SNOWLIGHT and SNOWRUST for initial access and reconnaissance, employing techniques such as PowerShell scripts and SMB share discovery. UAT-8302 also establishes backdoor access through proxy servers and uses tools like Stowaway for tunneling traffic. Their operations indicate a close relationship with other known China-nexus threat actors, leveraging shared malware families and TTPs.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "34f06d4a-8497-40ab-8614-bba6fd4754a3"
        },
        "7461ca39-3331-4b67-b4f8-a88de1c46768": {
          "name": "Earth Naga",
          "version": "1.1",
          "description": "Earth Naga is an APT group that has persistently targeted high-value organizations, including government agencies, telecommunications, and military-related manufacturers, primarily in Taiwan and the broader APAC region. They have been linked to the use of Draculoader and ShadowPad C&C infrastructure, demonstrating sophisticated TTPs such as establishing SSH connections through compromised mail servers. Earth Naga has collaborated with Earth Estries, sharing access to facilitate continued exploitation, complicating detection and attribution efforts. Their operations reflect a growing interest in global intelligence collection, extending to NATO member countries and Latin America.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "7461ca39-3331-4b67-b4f8-a88de1c46768"
        },
        "480b325a-7a08-44ae-8690-1ba5eaf9c899": {
          "name": "Lamashtu",
          "version": "1.1",
          "description": "Lamashtu is a financially motivated data-theft and extortion group that emerged in mid-April 2026, operating a Tor-hosted leak site (Lamashtu[.]Blog) with countdown timers, structured Breach Impact Reports, and proof-of-life thumbnails to pressure victims. The group has claimed 17+ victims across France, Romania, Thailand, Malaysia, Egypt, and the UAE within its first weeks of activity, targeting energy, pharmaceutical, retail, hospitality, and film sectors, with confirmed exfiltration totaling 760+ GB.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "480b325a-7a08-44ae-8690-1ba5eaf9c899"
        },
        "0c78182d-bc4b-404f-aacc-40538252b58c": {
          "name": "NyxarGroup",
          "version": "1.1",
          "description": "NyxarGroup is a threat actor involved in a coordinated data brokerage ecosystem across Latin America, primarily targeting government infrastructure. They have published high volumes of data, including 110,000 records from Chile's Servicio Civil platform and 250GB from the Ley del Lobby platform, which tracks lobbying activities. The data exfiltrated includes limited fields but provides a directory of Chilean government employees, enhancing the visibility of the public sector workforce. NyxarGroup's activities indicate a focus on exploiting government transparency and training systems for data leaks.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "0c78182d-bc4b-404f-aacc-40538252b58c"
        },
        "df383083-f43a-4bf8-9757-ce2bf1def292": {
          "name": "UNC6748",
          "version": "1.1",
          "description": "UNC6748 targets users in Saudi Arabia through a fake Snapchat website, employing a backdoor known as GHOSTKNIFE for data exfiltration. Their exploitation process initially featured basic obfuscation, which evolved to include anti-debugging measures. The actor primarily leveraged CVE-2025-31277 and CVE-2026-20700 for RCE exploits, but exhibited inconsistencies in exploit support for different iOS versions. Additionally, UNC6748's delivery mechanisms incorporated session storage checks to manage infection attempts.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "df383083-f43a-4bf8-9757-ce2bf1def292"
        },
        "05cf269a-1731-45a6-bcd3-eff1afcca2bb": {
          "name": "FlowerStorm",
          "version": "1.1",
          "description": "FlowerStorm is a phishing-as-a-service platform that mimics legitimate services to bypass multi-factor authentication structure. The majority of its targets are located in North America and Europe, with a significant focus on organizations in the United States. FlowerStorm's operational mistakes have led to vulnerabilities that can be exploited for disruption and analysis.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "05cf269a-1731-45a6-bcd3-eff1afcca2bb"
        },
        "712d2b58-5e2e-4106-b5aa-65c5b7d99e44": {
          "name": "Mr_Rot13",
          "version": "1.1",
          "description": "Mr_Rot13 is a stable hacking group identified through a PHP backdoor and a Downloader domain linked to a C2 infrastructure active since 2020. They utilize the Rot13 algorithm for obfuscation and have demonstrated a low detection rate across security products, indicating advanced operational security. Their activities include exploiting CVE-2026-41940 to deliver malicious payloads and maintaining covert communication via Telegram. The group has shown a particular focus on WordPress as a target, with ongoing operations that suggest a sophisticated threat actor rather than opportunistic attackers.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "712d2b58-5e2e-4106-b5aa-65c5b7d99e44"
        },
        "a2553b72-e87f-40c6-afe2-04df4cf3e12f": {
          "name": "Shadow-Earth-053",
          "version": "1.1",
          "description": "SHADOW-EARTH-053 is a China-aligned threat group exploiting unpatched Microsoft Exchange Server vulnerabilities, specifically CVE-2021-26855, to conduct cyberespionage against government and defense-linked targets across Asia and Europe. The group primarily deploys ShadowPad malware, utilizing techniques such as credential dumping, tunneling tools, and lateral movement via WMIC. They have also been observed installing web shells for persistence and leveraging a custom ExchangeExport tool to extract high-value mailbox contents. Additionally, low-confidence associations with Noodle RAT and CVE-2025-55182 have been noted in their operations.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "a2553b72-e87f-40c6-afe2-04df4cf3e12f"
        },
        "85652df8-67e5-4c25-baad-147bd1eb2d80": {
          "name": "Hive0163",
          "version": "1.1",
          "description": "Hive0163 is a financially motivated ransomware group responsible for deploying Interlock ransomware, utilizing ClickFix social engineering for initial access. They employ the AI-generated PowerShell backdoor Slopoly for persistent command-and-control access, which checks in with attacker infrastructure every 50 seconds and transmits telemetry every 30 seconds. The group leverages AzCopy for bulk data exfiltration to Azure blob storage before executing ransomware, employing a five-stage attack chain. Their operations are characterized by the use of initial access brokers and a variety of custom backdoors for long-term access and data exfiltration.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "85652df8-67e5-4c25-baad-147bd1eb2d80"
        },
        "7e039dd6-e2cd-4fab-9be9-85d6a5ea1eb3": {
          "name": "LulzIntel",
          "version": "1.1",
          "description": "The threat actor lulzintel has claimed responsibility for multiple data breaches, including those of vegehome.pl, Almaex, Smaregi, and Kin Teck Tong, exposing sensitive information of over 400,000 individuals combined. The breaches involved the release of customer and patient records, including personal details and medical histories.Sample data has been provided to demonstrate the validity of the claims.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "7e039dd6-e2cd-4fab-9be9-85d6a5ea1eb3"
        },
        "7ff63e0c-2345-4282-b4d7-0e5dc49dfc60": {
          "name": "Storm-2561",
          "version": "1.1",
          "description": "Storm-2561 is a cybercriminal threat actor known for a credential theft campaign that employs SEO poisoning to distribute fake VPN clients. The campaign redirects users to malicious ZIP files containing digitally signed trojans that harvest VPN credentials, leveraging user trust in search engine results. The malicious components are signed by “Taiyuan Lihua Near Information Technology Co., Ltd.” and were hosted on GitHub repositories that have since been taken down. This operation exhibits characteristics consistent with financially motivated cybercrime.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "7ff63e0c-2345-4282-b4d7-0e5dc49dfc60"
        },
        "ee12e0a9-a20b-4d48-8814-d565211cb0ba": {
          "name": "Amethyst Rain",
          "version": "1.1",
          "description": "Microsoft threat actor profile. Origin/Threat: Lebanon.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "ee12e0a9-a20b-4d48-8814-d565211cb0ba",
          "alias": [
