        "e8d5248b-0ccb-43ec-b7e2-7c669dfc7be2": {
          "name": "Larva-24009",
          "version": "1.1",
          "description": "Larva-24009 has been active since at least 2023, conducting phishing email attacks to install malware globally, particularly targeting users in Korea. The actor employs LNK malware to install a PowerShell backdoor and maintains persistence with remote control tools like QuasarRAT and UltraVNC. They utilize phishing emails with keywords such as “hospital survey” and “resume,” disguising malware as document files to trick users into execution. This results in the theft of sensitive information, including credentials and user files.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "e8d5248b-0ccb-43ec-b7e2-7c669dfc7be2"
