        "03fc61f9-cb50-45db-8eb3-c586e5847b3a": {
          "name": "GlobalSecretGroup",
          "version": "1.1",
          "description": "Global Secret is a ransomware group that has claimed attacks on various organizations across multiple countries, including the USA, India, and Brazil.",
