          "id": "ccf8ceb7-a926-4a29-b045-fb99f24025ba"
        },
        "f06cd97d-3e32-4f45-99a3-c1415b1f5760": {
          "name": "ModernStealer",
          "version": "1.1",
          "description": "ModernStealer is linked to underground posts offering sensitive military, government, nuclear, and aerospace material, with connections to a Session contact identifier and a Telegram account named Sassoon Don. Analysts identified five ModernStealer listings and eight government-related listings, including references to Pakistan’s NUST and SUPARCO, as well as US defense entities. The shared identifier suggests operational overlap with other identities, but does not confirm a direct link between them. The actor exemplifies the importance of tracking durable identifiers over forum names in threat intelligence.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "f06cd97d-3e32-4f45-99a3-c1415b1f5760"
        },
        "6d957a9b-c674-41bd-bcef-31f7f4f843ae": {
          "name": "Larva-26009",
          "version": "1.1",
          "description": "Larva-26009 targets MS-SQL servers and has been observed installing the XMRig CoinMiner.",
