        "c539a88d-191a-4886-ac65-2e5150e57880": {
          "name": "Larva-26005",
          "version": "1.1",
          "description": "Larva-26005 is a threat actor confirmed to be distributing Xctdoor, a RAT, to users in Korea. The malware was initially disclosed in 2024 and was later found disguised as an integrated security program in an attack case reported by Hauri in 2026.",
