          ],
          "id": "ff6da609-9651-445d-b448-0ce9c372faec"
        },
        "f668a512-ecf2-40ef-b75d-51b3aa9a121a": {
          "name": "VantaCore",
          "version": "1.1",
          "description": "VantaCore is a ransomware group believed to be a rebrand of Thor, targeting Russian organizations with custom-built malware and multimillion-dollar ransom demands. F6 says the group has attacked at least seven victims, uses a ransomware-as-a-service model, and reflects a broader shift among pro-Ukrainian hackers toward in-house tooling instead of LockBit 3 Black and Babuk.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "f668a512-ecf2-40ef-b75d-51b3aa9a121a",
