            "Thor"
          ]
        },
        "15162648-c1f4-4da6-90ac-4bc7b8ec9406": {
          "name": "CRPxO",
          "version": "1.1",
          "description": "CRPxO is a ransomware group that has claimed responsibility for attacks on various organizations, including Encore Enterprises, Inc., KUVEYT TURK, and Johnson & Johnson, among others. The group has targeted entities across multiple countries, including the USA, Turkey, South Korea, Australia, the UK, and China. NCC Group has noted that the claims of responsibility from CRPxO have not been confirmed and highlighted inconsistent evidence regarding their involvement in these attacks.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "15162648-c1f4-4da6-90ac-4bc7b8ec9406"
        },
        "be618f7e-e6bf-4dcb-b805-695224885c49": {
          "name": "ShadowByt3$",
          "version": "1.1",
          "description": "ShadowByt3$ is a ransomware group known for exfiltrating sensitive data from various organizations, including John Engel Team, Abbott Laboratories, and Nintendo of America, often demanding substantial ransoms. They employ techniques such as SQL injection to breach systems and threaten to leak stolen data if negotiations are not completed within a specified timeframe. The group has also claimed to operate as a Wiper as a Service (WaaS), focusing on data theft and potential data destruction. Their activities include targeting a range of sectors, from education to healthcare, and they have been linked to mass-scanning campaigns for vulnerabilities.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "be618f7e-e6bf-4dcb-b805-695224885c49"
        },
        "9775d015-39d4-4759-b6d0-2e5413cfe3f3": {
          "name": "DaOnlySpark",
          "version": "1.1",
          "description": "DaOnlySpark is a forum actor claiming to have leaked sensitive data from AdvaCare, including internal financial details, and from Jinko, comprising 3.7 GB of patient records, clinical profiles, and private messages. Both claims remain unverified.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
