        "46b65f4d-9550-4164-a500-2c32ea243b92": {
          "name": "IAmNotAVillain",
          "version": "1.1",
          "description": "IAmNotAVillain is a threat actor that claimed responsibility for a data breach at Revolut, threatening to sell confidential customer records unless a ransom of $3 million is paid. They asserted that they compromised an Italian government email system and communicated with Revolut for months. The group published an ultimatum online and created a new Telegram channel for further communication.",
