        "55dd69cb-a166-46f7-af51-d09e3657a191": {
          "name": "CikLeak",
          "version": "1.1",
          "description": "CikLeak is a threat actor that claims to have accessed systems of Russia’s Central Election Commission and companies involved in the Vybory platform, which administers elections. The group asserts that its objective is to expose internal workings of the Russian electoral system and potential manipulation opportunities, rather than disrupt voting. Prior to their disclosure, Russian officials conducted a security assessment of the Vybory portal and identified vulnerabilities in the video surveillance system.",
          "icon": "",
