        "edc11644-6375-4760-8403-0153bd092aa0": {
          "name": "GTG-20006",
          "version": "1.1",
          "description": "GTG-20006 is a Russian espionage operator that has targeted over 20 organizations in Ukrainian and European government, defense, and diplomatic sectors, exfiltrating more than 300,000 national identity records. The actor employs an auto-rebuild loop for flagged implants to evade detection and has delivered payloads that freeze victim machines' security updates. GTG-20006 has also been linked to an intrusion into a North African government technology authority, compromising a central account server to exfiltrate a credential database. The group utilizes customized AI-driven workflows throughout its attack chain.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "edc11644-6375-4760-8403-0153bd092aa0"
        },
        "20200364-8b07-488a-a1e2-7b5e8be6a785": {
          "name": "V0idix",
          "version": "1.1",
          "description": "V0idix is a threat actor known for distributing leaked data for free on leak forums, with some files requiring a reply-to-unlock to access.",
