        "b687defa-308c-4f9e-bb9e-d9d30fb4b1a0": {
          "name": "Storm-2992",
          "version": "1.1",
          "description": "Financially motivated threat actor tracked by Microsoft Threat Intelligence as the developer and support operator of the EvilTokens phishing-as-a-service platform, advertised and sold to other cybercriminals through Telegram channels. Storm-XXXX is Microsoft's designation for a developing or emerging activity cluster: the name is provisional and may be merged or renamed once attribution matures. Its infrastructure was disrupted by Microsoft's Digital Crimes Unit with partners in September 2026.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "b687defa-308c-4f9e-bb9e-d9d30fb4b1a0"
        },
        "d7140683-7af8-41c6-8938-18a69bb809e3": {
          "name": "TA419",
          "version": "1.1",
          "description": "According to Proofpoint, TA419 is a China-aligned, espionage-motivated threat actor conducting regular targeted credential phishing campaigns against individuals at US- and Japan-based think tanks, defense contractors, universities and law firms since at least April 2025. In 2026 it impersonated real subject-matter experts, including a former White House OSTP official and a senior Anthropic employee, to target AI policy experts. Benign rapport-building emails are followed by multi-stage URL redirection to an adversary-in-the-middle phishing page against Microsoft 365 / Entra ID, built on a customised Frameless BitB kit embedding an Evilginx phishlet. Proofpoint states the group's activity had not been previously reported publicly.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "d7140683-7af8-41c6-8938-18a69bb809e3"
        },
        "afd10845-ea76-4251-b385-f51a32c2dcec": {
          "name": "ZaWoo",
          "version": "1.1",
          "description": "ZaWoo is a ransomware group that has claimed multiple attacks on various organizations across different countries, including France, New Zealand, Germany, the USA, Canada, and the Czech Republic. Their operations have resulted in encrypted and compromised systems, leading to potential disruptions in victim operations. Notable targets include ambpvc, zenithtechnology.co.nz, and fes-sport.de.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "afd10845-ea76-4251-b385-f51a32c2dcec",
          "alias": [
            "ZaWoo Team"
          ]
        },
        "eb8fb25d-ba4f-4970-ae8a-b0020b2b9841": {
          "name": "BlackLock",
          "version": "1.1",
          "description": "BlackLock is a ransomware group established around March 2024, operating under a RaaS model and actively recruiting affiliates. The ransomware is developed in Go, enabling cross-platform attacks on Windows, Linux, and VMware ESXi environments, and employs ChaCha20 for file encryption. BlackLock appends encryption keys and metadata to files for decryption post-ransom payment and utilizes a covert method to delete Volume Shadow Copy Service data to hinder recovery efforts. The group has been linked to operational failures due to significant OPSEC mistakes, including a breach of its leak site that exposed internal data.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "eb8fb25d-ba4f-4970-ae8a-b0020b2b9841",
          "alias": [
            "El Dorado",
            "BlackLocks",
            "Eldorado",
            "Mamona",
            "GLOBAL GROUP"
          ]
        },
        "G1058": {
          "name": "[Enterprise] The Gentlemen",
          "version": "1.2",
          "description": "[The Gentlemen](https://attack.mitre.org/groups/G1058) is a group that maintains the [The Gentlemen Ransomware](https://attack.mitre.org/software/S9051)-as-a-service (RaaS). [The Gentlemen](https://attack.mitre.org/groups/G1058) was first observed in mid-2025 who had posed [The Gentlemen Ransomware](https://attack.mitre.org/software/S9051) as a closed ransomware and shortly later opened the ransomware as a RaaS to affiliates in September 2025. [The Gentlemen](https://attack.mitre.org/groups/G1058) has been affiliated with the threat group Storm-2697 and GOLD SHERWOOD.(Citation: MSTI_GentelmenRansomware_May2026)(Citation: Intel471_TheGentlemen_Aug2026)(Citation: Sophos_TheGentlemen_Sept2026)(Citation: SoučekESET_Gentlemen_Jun2026)(Citation: CheckPointResearch_TheGentlemen_April2026)(Citation: BradyUnit42_TheGentlemen_July2026)(Citation: CarveyODonnellWelchHuntress_TheGentlemen_May2026)(Citation: TrendAI_TheGentlemen_Sept2025) ",
          "icon": "",
