        "c1ef86d7-ab86-4188-91d2-af3f36207d96": {
          "name": "UNC7017",
          "version": "1.2",
          "description": "Uncategorized threat cluster tracked by Google Threat Intelligence Group and Mandiant, responsible for an ephemeral supply chain compromise of AOMEI Backupper between April and July 2026, investigated with ManageEngine's Threat Analysis Lab (METAL). The actor briefly modified the down_html.ini and Notifycfg.ini configuration files on AOMEI's origin servers for windows of five to ten minutes, redirecting the update and promotion flow to an attacker-hosted archive, then restored them. It deployed the CROSSROAD downloader and the SHINYROAD backdoor through trojanized Radmin components, later Adaptix C2, and on one occasion coerced NetNTLMv2 authentication through a hidden WebDAV popup. Victims were opportunistic, in IT services, telecommunications and higher education across several countries. No state nexus has been stated.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "c1ef86d7-ab86-4188-91d2-af3f36207d96"
        },
        "b101baba-907b-4aba-8ea2-1f77e53eb782": {
          "name": "REF8801",
          "version": "1.2",
          "description": "Intrusion set tracked by Elastic Security Labs, posing as a Web3 venture accelerator (Apex Accelerator / Apex Arena, Apex Foundation) to target cryptocurrency start-ups and founders. Lures offer investment, free AI credits and security audits, and lead victims to install npm packages (@apexacc/cli, @apexacc/audit) that fetch platform-specific payloads: the CloudSyncD backdoor on macOS and a custom information stealer exfiltrating through Telegram on Windows. The packages also repackage a legitimate coding agent to route LLM traffic through attacker infrastructure and register an attacker-controlled MCP server in the victim's agent configuration. Earlier npm packages from the same operation were reported by SafeDep in July 2026. Elastic makes no state or group attribution.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "b101baba-907b-4aba-8ea2-1f77e53eb782"
        },
        "98ff9870-3da1-4642-be8c-df6834623b23": {
          "name": "GhostAction",
          "version": "1.2",
          "description": "Software supply chain campaign and its unnamed operator, first reported by GitGuardian in September 2025: malicious GitHub Actions workflows named \"Github Actions Security\" injected into compromised repositories exfiltrated CI/CD secrets, with 3,325 secrets stolen from 817 repositories. In October 2026 OpenSourceMalware reported a renewed wave and a second stage that no longer needs a CI runner: a .vscode/tasks.json launcher with a folderOpen trigger runs a Node.js credential stealer disguised as public/fonts/fa-solid-400.woff2, installs a cron job polling the operator's server, and is backed by a fallback workflow. OpenSourceMalware calls this stage a copycat of the DPRK PolinRider technique rather than an extension of it, and ties it to GhostAction through shared server infrastructure. A phishing kit on the lookalike domain my-github.com, harvesting credentials and silently authorizing an OAuth application with repo and workflow scopes, was reported on the same infrastructure.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "98ff9870-3da1-4642-be8c-df6834623b23"
        },
        "57eb1be4-526a-4fa4-8dc4-ec8edb9564ad": {
          "name": "k0t",
          "version": "1.2",
          "description": "k0t (also CryptoFeel, Member19, QazWsxShop) is a financially motivated cybercriminal actor, first seen on 22 October 2025, behind a large-scale campaign against exposed network edge devices, according to a joint investigation by Group-IB and NyxLab published in October 2026. The actor finds targets by mass enumeration with FOFA and ZoomEye rather than by researching specific organizations. It gains access by exploiting known flaws such as CVE-2025-64446 (FortiWeb) and CVE-2026-0257 (PAN-OS/Prisma Access) with custom Python scripts, or by brute-forcing Fortinet FortiGate and Palo Alto GlobalProtect appliances, then connects over OpenConnect VPN. Post-exploitation relies on NetExec, Impacket, noPac, Kerbrute, PetitPotam and Mimikatz, persistence on MeshCentral, Atera, Teramind, AnyDesk and AdaptixC2, and exfiltration on Rclone to Wasabi S3 and MEGA. More than 70,000 exposed credentials are linked to the campaign, with victims mostly in Asia Pacific and Latin America; the actor states that the US and Canada are its priority. Many victims were later listed by the Qilin and The Gentlemen ransomware groups, so k0t is assessed to be an initial access broker or affiliate, but the exact relationship is unclear. The activity partially overlaps in time with the FortiBleed credential-harvesting cluster, with negligible overlap in compromised data.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "57eb1be4-526a-4fa4-8dc4-ec8edb9564ad",
          "alias": [
            "CryptoFeel",
            "Member19",
            "QazWsxShop"
          ]
        },
        "5869bc41-c58a-4e06-9419-b3874a4d3a12": {
          "name": "Jingle Thief",
          "version": "1.2",
          "description": "Jingle Thief is a financially motivated gift card fraud campaign documented by Palo Alto Networks Unit 42 in October 2025 and tracked as cluster CL-CRI-1032, assessed with moderate confidence to be run by Morocco-based attackers active since 2021, not affiliated with a nation-state. It targets cloud environments of large retail and consumer services organizations: phishing and smishing harvest Microsoft 365 credentials, then the actors, without malware, perform SharePoint and OneDrive reconnaissance of gift card issuance workflows, send internal phishing from compromised accounts, set forwarding rules, and persist by registering rogue authenticator apps and enrolling devices in Entra ID; in one case access lasted about 10 months across more than 60 accounts. Unit 42 assesses with moderate confidence that CL-CRI-1032 overlaps with the actors publicly tracked as Atlas Lion and Storm-0539; it is kept as a separate entry and linked to Storm-0539 as similar. In October 2026, 404 Media reported an organized crime gang that hacked Staples and issued millions of dollars in gift cards; The Hacker News related this to Jingle Thief, but the reporting does not attribute that intrusion to the cluster.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "5869bc41-c58a-4e06-9419-b3874a4d3a12",
          "alias": [
            "CL-CRI-1032"
          ]
        },
        "aa09600e-29a2-4ba0-a6c0-bd305c30140c": {
          "name": "STAC4749",
          "version": "1.2",
          "description": "STAC4749 is a financially motivated activity cluster reported by Sophos in July 2026, observed between February and June 2026 against dozens of organizations, nearly 95% of them in Canada and the U.S. Operators contact victims through Microsoft Teams chats and calls impersonating IT support, using plausible employee usernames on IT-themed '.top' cloud domains rather than onmicrosoft.com tenants, and obtain a remote session through Microsoft Quick Assist or, increasingly from April 2026, the RemSupp RMM tool; RDP is then enabled for lateral movement. PowerShell retrieves a loader communicating over gRPC with hard-coded C2 addresses and checking for an appscreen.log file, later replaced by a PyArmour-obfuscated PyInstaller backdoor that fetches its AES key from a public GitHub repository and talks to workers.dev infrastructure, followed by Golang implants launched with a '--token-raw' argument and pinning embedded CA certificates (issuers such as loop-CA, connectify-CA, james-bond-CA), plus a reverse SOCKS proxy. Persistence relies on HKCU Run keys masquerading as Realtek or WinAudio components and hidden Startup shortcuts; DWAgent and AnyDesk provide redundant access. At least three intrusions ended in Chaos ransomware deployment (the RaaS reportedly launched by former BlackSuit members, not the Chaos builder lineage), in one case under 17 hours after initial access. Sophos notes a Russian-keyboard typo in operator commands, found no evidence of a link to MuddyWater, and states the evidence is insufficient for attribution. In October 2026 Arctic Wolf, analysing more than 400 Teams IT-support impersonation incidents, stated that the shift to '.top' tenants aligns with Sophos's reporting on STAC4749. The Sophos loader shares its artifacts (sekv-prefixed filename, 'Realtek HD Audio' Run value, appscreen.log check, gRPC C2) with the GoGRPC backdoor documented by Zscaler ThreatLabz, although neither vendor equates the two.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "aa09600e-29a2-4ba0-a6c0-bd305c30140c"
        },
        "01219d2a-9038-4a42-9090-2b4e964afb26": {
          "name": "Scarlettgroup",
          "version": "1.2",
          "description": "ScarlettGroup is a newly observed cyber extortion gang actively threatening companies via a dark web leak site, employing countdown timers to pressure victims. Their operational TTPs include public listing of alleged breaches and a negotiation window for communications. While the group’s intrusion methods remain unverified, their public threats and activity on forums such as PwnForums indicate a growing trend in cyber extortion.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "01219d2a-9038-4a42-9090-2b4e964afb26"
        },
        "a92ce123-9be2-4a2e-a972-ca3ebdafe88c": {
          "name": "UAT-10147",
          "version": "1.2",
          "description": "UAT-10147 is a Chinese-speaking, financially motivated threat actor targeting internet-facing Windows and Linux servers through the exploitation of publicly disclosed vulnerabilities. The group employs advanced techniques including AI-assisted workflows, deploying malware such as SPECTRE and various RATs, and utilizing capabilities like remote code execution and privilege escalation. Their operations are characterized by the integration of AI for reconnaissance, exploit refinement, and persistent access management. UAT-10147 has a target list of approximately 170,000 URLs and impacts various sectors, including government and education.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "a92ce123-9be2-4a2e-a972-ca3ebdafe88c"
        },
        "a5a31ba2-d519-4b5d-9122-656714c28641": {
          "name": "Mimori",
          "version": "1.2",
          "description": "Mimori is a data-extortion / ransomware group first observed on 2026-10-20, when it launched a leak site and listed its first two claimed victims: OpenText (Canada, technology) and AVEVA (UK, industrial software), claiming 177,234 files from AVEVA. A third claimed victim, St. James's Place (UK, financial services), was reported on 2026-10-21. The leak site, mimori.group, is a clearnet domain fronted by Cloudflare that publishes victim pages under /organizations/<victim> and threatens to publish stolen data unless victims make contact. None of the claims has been independently verified. AVEVA and OpenText have each disclosed a separate security incident (unauthorized access to AVEVA's corporate SharePoint, and to an OpenText employee account through social engineering), but neither has attributed it to Mimori. No ransomware sample, encryptor or affiliate program has been publicly linked to the group, and its operators and any links to earlier groups are unknown.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "a5a31ba2-d519-4b5d-9122-656714c28641"
        },
        "6722873c-8fe6-44d9-98ea-91e6c32c7f2c": {
          "name": "Whitearmor",
          "version": "1.2",
          "description": "WhiteArmor is a data-theft and extortion group that appeared in October 2026. It claimed its first victim, Whirlpool, around 21 October 2026, and runs a Tor data leak site plus a clearnet mirror (whitearmor.cc). Within its first week it named 14-19 organisations, mainly in the United States, across the transportation/logistics (J.B. Hunt, Ryder, Echo Global Logistics), retail (Lovesac), consumer electronics (Hisense), online gambling (Gamdom) and political (Partido Liberal, Argentina) sectors. Its most publicised claim is 19 GB of Hisense warranty, customer, supplier and CRM data covering Malaysia and Singapore, for which it demanded USD 5 million in Bitcoin, reportedly raised from USD 500,000. Reports describe an affiliate model with a 5% operator fee and say the group is recruiting pentesters, web exploitation specialists and zero-day researchers. No encryptor has been publicly analysed, and none of the victim claims had been independently confirmed at the time of reporting.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "6722873c-8fe6-44d9-98ea-91e6c32c7f2c"
        },
        "9d0e4a28-8765-45c5-9cf8-18c5d11235b0": {
          "name": "UAT-6275",
          "version": "1.2",
          "description": "UAT-6275 is a cyberespionage actor targeting government organizations across Central Asia and the CIS, with a focus on diplomacy, economic development, and environmental management. The group employs custom RATs like Chvost, Laplas, and PickleShell, leveraging methods such as WinRAR exploits and malicious documents for payload delivery. Evidence indicates UAT-6275 has a Kazakhstan nexus, supported by Russian-language artifacts and specific operational hours. Its activity includes the creation of publicly accessible malware staging directories and interest in expanding to additional platforms, including Linux.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "9d0e4a28-8765-45c5-9cf8-18c5d11235b0"
        },
        "ae595356-f187-4e54-9ee5-10d77db32f23": {
          "name": "CyberCartel",
          "version": "1.2",
          "description": "CyberCartel is a Latin American e-crime group employing a multi-agent system called CARLIY0S to coordinate attacks against financial institutions and payment providers. The group's operations utilize AI models for deep reconnaissance, zero-day vulnerability analysis, exploit code generation, and credential harvesting. They have targeted over 400 financial entities in Latin America and are linked to campaigns involving malicious Chrome extensions aimed at stealing credentials and financial data. Active since 2012, CyberCartel has evolved to incorporate Malware-as-a-Service from established malware families to breach Chromium-based browsers.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "ae595356-f187-4e54-9ee5-10d77db32f23"
        },
        "f55c5d80-2ccf-488b-b90a-5cc97048141b": {
          "name": "DataSuckers",
          "version": "1.2",
          "description": "DataSuckers is a financially motivated hacking group linked to major data breaches affecting businesses in Russia and Ukraine, with claims of having stolen 2-3 TB of data from approximately 68 million customers. The group has demonstrated TTPs such as customer data theft, extortion through ransom demands, and website defacement. They have claimed responsibility for high-profile attacks on ATB Market, Dodo Pizza, and Tez Tour, and reportedly obtained sensitive customer and employee information during these breaches. While DataSuckers maintains a Telegram channel for communications, its operations have drawn the attention of Russian authorities, resulting in the detention of several key members.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "f55c5d80-2ccf-488b-b90a-5cc97048141b"
        },
        "785a6aea-7a98-4290-8497-2e665b1115b3": {
          "name": "Earth Sirrush",
          "version": "1.2",
          "description": "Earth Sirrush has conducted sustained spear-phishing campaigns against Ukrainian governmental and defense entities, deploying PowerShell and Go-based tools such as LONEPAGE and SEAGLOW, delivered via malicious archives and exploiting CVE-2023-38831. Their operations transitioned to image-based steganography in the CINDERBLOT campaign, using phishing lures that impersonate Ukrainian state services. Despite continuously adapting their tooling, identifiable indicators of compromise can link their campaigns, demonstrating consistent development habits and delivery patterns. Their targets have included the National Police, State Border Guard Service, and various ministries related to logistics and defense supply chains.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "785a6aea-7a98-4290-8497-2e665b1115b3",
          "alias": [
            "SHADOW-EARTH-065"
          ]
        },
        "9a15723b-0148-4807-b8bf-b5bdca7bf725": {
          "name": "DarkBlinders",
          "version": "1.2",
          "description": "DarkBlinders hackers are deploying a fake video meeting application to establish a backdoor and facilitate cyberespionage against Israel and the Kurdistan Region of Iraq. Their operations have led to compromises within a government cloud environment in Kurdistan and targeting a significant Israeli individual linked to security. They are also abusing GitHub repositories as part of their TTPs. The investigation has confirmed their focused efforts in this cyber campaign.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "9a15723b-0148-4807-b8bf-b5bdca7bf725"
        },
        "749b849c-11a6-4ec5-9a56-67caa72fd0bc": {
          "name": "Xuanye Group",
          "version": "1.2",
          "description": "Xuanye Group is implicated in a breach at ASOS, utilizing social engineering to impersonate a trusted contact and obtain login credentials. They claimed responsibility for the attack, asserting the theft of customer data while clarifying that financial information was not compromised. The group linked their activities to a Telegram channel and threatened to leak stolen data unless negotiations commenced. They have not provided evidence of the stolen data, despite reportedly sharing it with BBC News.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "749b849c-11a6-4ec5-9a56-67caa72fd0bc"
        },
        "87e0e168-99df-4863-9fd1-23f529c5f24c": {
          "name": "UAT-11473",
          "version": "1.2",
          "description": "Highly sophisticated APT reported and named by Cisco Talos that exploited CVE-2026-20127, an authentication bypass in Cisco SD-WAN Catalyst Controller, to gain unauthorized access and install the custom KeyDrift malware framework (PolyFlame, LittleFilch), designed for long-term persistent access and automated exfiltration of sensitive keying material from SD-WAN control-plane processes. Observed targeting spans space and satellite services, defense and aerospace technology, and policy research. Talos assesses with high confidence that UAT-11473's operating infrastructure overlaps considerably with Volt Typhoon's Silent Train covert access network; this infrastructure overlap is the only link Talos reports between the two.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "87e0e168-99df-4863-9fd1-23f529c5f24c"
        },
        "c2a10fc3-a12f-4310-94c2-88a1eb136719": {
          "name": "GOLD OGRE",
          "version": "1.2",
          "description": "Cybercriminal group tracked by the Sophos Counter Threat Unit (CTU) that operates the Aur0ra ransomware (also known as Aurora ransomware). Sophos reports that the group used AI extensively: it tested the evasion capabilities of tools and techniques against several EDR products in an AI-assisted post-exploitation framework built with Cursor, then gave its associates similar technology for Aur0ra intrusions, in which Cursor's Composer agent and models from Anthropic, xAI and Moonshot performed network and Active Directory discovery, password spraying, Kerberoasting, NTLM coercion and relay and credential extraction, with human operators supplying VPN credentials, SOCKS access and objectives; guardrails were bypassed by framing the intrusions as authorized red team or diagnostics testing. Intrusions relied on Cobalt Strike, shared C2 infrastructure, SharpShares enumeration and exfiltration to S3-compatible storage, and victims were later named on Aur0ra's data leak site. Multiple distinct operators followed the same pattern; artifacts suggest Russian speakers.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "c2a10fc3-a12f-4310-94c2-88a1eb136719"
        },
        "4125764c-ec9a-4a11-88c3-140d8b6e2810": {
          "name": "Vapor Panda",
          "version": "1.2",
          "description": "China-nexus targeted intrusion adversary tracked by CrowdStrike, formerly tracked as VexatiousTemper, active since at least 2021 against government, think tank, energy and extractive organisations across Europe, North America, Oceania and the UK. From 17 October 2026 CrowdStrike observed it run the agentic AI framework ARTEX, mainly with DeepSeek plus a second commercial LLM, from a single controller against more than 200 organisations in at least 14 countries, including foreign ministries in Latin America, Europe, Asia and the Middle East, US pharmaceutical, semiconductor, defense and nuclear organisations, and telecommunications providers. A human operator steered the agents in Chinese, including instructions to find hosts without the CrowdStrike Falcon sensor. Post-exploitation at nine organisations included deployment of the BLOODALCHEMY backdoor, side-loaded by a renamed GameHook binary. CrowdStrike states this campaign is separate from the ARTEX activity tracked as Storm-0940. The Hacker News reports, without a CrowdStrike quote, that the group overlaps with Trend Micro's Earth Estries; this overlap is recorded as a similar relation, not as a synonym.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "4125764c-ec9a-4a11-88c3-140d8b6e2810",
          "alias": [
            "VexatiousTemper"
          ]
        },
        "a7e30dc5-6efd-4d0b-ba09-ce8a3a573c96": {
          "name": "UNC7228",
          "version": "1.2",
          "description": "Uncategorized threat cluster tracked by Google Threat Intelligence Group for an ARTEX-enabled intrusion campaign also tracked by Wiz Research. GTIG states that it overlaps with the PRC-nexus actor Microsoft tracks as Storm-0940. Activity dates back to at least August 2026 and affected multiple entities in the US and Europe in enterprise software, industrial automation, semiconductor manufacturing and design, and telecommunications. The actor typically moved from a first compromised account to deep system access in about four hours, once in 15 minutes, customised its tooling to victim-specific setups and fell back to open proxies when its infrastructure was blocked. The overlap with Storm-0940 is recorded as a similar relation, not as a synonym.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "a7e30dc5-6efd-4d0b-ba09-ce8a3a573c96"
        },
        "529ab5a8-b53d-4c4d-b2c2-75f13a5eaaa6": {
          "name": "UTA0576",
          "version": "1.2",
          "description": "Previously unknown threat actor tracked by Volexity, which from 3 October 2026 exploited a zero-day chain in Ivanti Connect Secure (authentication bypass and RCE tracked as CVE-2026-104935, plus a privilege escalation) to obtain unauthenticated root code execution on a fully patched appliance (22.8R2.4). It re-ran the whole exploit chain for each command instead of deploying a web shell or backdoor, and used in-memory Python, Perl and Bash stages. Post-exploitation focused on credential theft and reconnaissance: Active Directory exports and a custom LDAP tool searching for LAPS passwords and BitLocker recovery keys, parsing of the appliance's own packet captures for LDAP, HTTP Basic and NTLM credentials, a Python Kerberos implementation, and password spraying. Anti-forensic steps included selective log tampering, restoring patched in-memory components and evading the Ivanti Integrity Checker Tool. Volexity assesses with low confidence a criminal rather than espionage motivation, and with medium confidence that the actor uses LLMs for exploit development and post-exploitation.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "misp"
          ],
          "id": "529ab5a8-b53d-4c4d-b2c2-75f13a5eaaa6"
        }
      }
    },
