        "Windows Registry Key Access": {
          "name": "Windows Registry Key Access",
          "version": "1.0",
          "description": "The action of opening a specific Windows Registry key, typically to read its associated value. This activity can be used for system configuration, application settings retrieval, and security policies.",
          "icon": "",
          "link": "https://attack.mitre.org/datacomponents/DC0050",
          "tide.vocab.stages": []
        },
        "Windows Registry Key Creation": {
          "name": "Windows Registry Key Creation",
          "version": "1.0",
