    "detection.composition": {
      "metadata": {
        "name": "Detection Composition Strategy",
        "field": "detection.composition",
        "description": "Describes how signals should be used in conjuntion, or separated",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": []
      },
      "entries": {
        "Independent": {
          "name": "Independent",
          "version": "1.0",
          "description": "No composition performed, each signal can be treated as \nindependent, unrelated alerts.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "9fd1e42c-ff0d-468c-988c-8f0571d8f0f9"
        },
        "Combined": {
          "name": "Combined",
          "version": "1.0",
          "description": "All signals triggered for any entity can be grouped in a single signal. \nThis may be extremely useful to identify pan-environment compromises.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "975b9fb7-b08e-40c2-b637-d099535c4029"
        },
        "Threshold": {
          "name": "Threshold",
          "version": "1.0",
          "description": "Each signal must be considered separately - but only when a certain amount \nof repeated alerts triggers within a span on time.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "9fd1e42c-ff0d-468c-988c-8f0571d8f0f9"
        },
        "Entity": {
          "name": "Entity",
          "version": "1.0",
          "description": "When the same entity is appearing across alerts raised by signals, \nthey should be grouped around the entity into a single incident, case, \nor higher-order alert (alert of alert)\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "e9e5a900-8f5a-4c60-9986-055886d22738"
        },
        "Sequence": {
          "name": "Sequence",
          "version": "1.0",
          "description": "Signals must be tracked across time, and correlated based on a succession of events. \nParticularly useful for weak signals, but which assembled over time with reinforcing \nsignal provide a high fidelity detection - for example, anomalous logons.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "0812b927-9eee-439f-879c-b7cdc6c1bfc5"
        },
        "Risk": {
          "name": "Risk",
          "version": "1.0",
          "description": "Advanced strategy where signals contribute a risk score over time to entities \nin a permanent risk store. This allows weak and strong signals to coexist, while \nresponse switches from processing alerts to process a bundle of contributing signals \naround a high risk entity. This is essentially an evolution of the `Entity` and \n`Threshold` strategy, and adds a layer of risk calculation around entities using \nrepeated signals as risk contributors. Different signals may contribute differentially, \nand also include decaying factors.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "c5a6f86a-410e-4f98-91b3-ef366101ff7e"
        }
      }
    },
    "detection.methodology": {
      "metadata": {
        "name": "Detection Methodology",
        "field": "detection.methodology",
        "description": "Defines the technical approaches and methods used to implement detection logic.\nThese methodologies help categorize how a detection rule processes and analyzes data\nto identify potential security threats, suspicious activities, or malicious behavior.\n\nTracking which methodology is used helps understanding if there are any potential gaps in\nhow signals are implemented, understand which ones are not getting implemented due to\ncomplexity, or even track which types of approach results in the best outcomes.  \n",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": []
      },
      "entries": {
        "Artifacts": {
          "name": "Artifacts",
          "version": "1.0",
          "description": "Simple string matching between a set of artifacts (such as known executables)\nagainst a log source.  \n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "43c1bb4d-b74e-4bbd-be22-aae3d301ee51"
        },
        "Pattern Matching": {
          "name": "Pattern Matching",
          "version": "1.0",
          "description": "Signature style of detections, where string processing is done to identify\nknown simple patterns, for example a set of command line flags\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "5b418142-1d83-4520-bca0-6b10c2a87b88"
        },
        "Event Search": {
          "name": "Event Search",
          "version": "1.0",
          "description": "Filtering logs for specific security-relevant events, such as IDS alerts coming from\nnetwork appliances, without significant work. \n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "cd80b0e9-2656-4af9-94e3-a6e505c8e502"
        },
        "Statistical": {
          "name": "Statistical",
          "version": "1.0",
          "description": "Uses mathematical and statistical methods to analyze data to identify patterns \nthat may indicate malicious or suspicious activity. This approach \noften involves aggregating and correlating events to improve detection fidelity.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "eb826d84-4611-4d86-a55a-ff434bf59e4d"
        },
        "Behavioural": {
          "name": "Behavioural",
          "version": "1.0",
          "description": "Focuses on understanding and detecting malicious activities by analyzing \nsequences of actions or behaviors that deviate from normal operational patterns. \nThis approach often involves creating baselines of legitimate behavior and \nidentifying deviations that may indicate threats.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "7f3a9d2b-8c4e-4d3a-9b2e-1f2c3d4e5f6a"
        },
        "Anomaly": {
          "name": "Anomaly",
          "version": "1.0",
          "description": "Identifies deviations from established baselines or expected patterns in data, \nwhich may indicate malicious or suspicious activity.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "92f1d5fe-e326-40d9-af98-5b0cb334af00"
        },
        "Machine Learning": {
          "name": "Machine Learning",
          "version": "1.0",
          "description": "Leverages machine learning algorithms to analyze data patterns and identify\npotential malicious or anomalous behavior that traditional methods might overlook.\\\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "04c9fabc-1f9c-4526-a523-a4c020a8e145"
        },
        "Heuristic": {
          "name": "Heuristic",
          "version": "1.0",
          "description": "Uses a set of predefined rules or criteria to identify potentially malicious \nactivity based on known indicators or characteristics of threats, without \nrequiring exact matches.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "7862439c-3358-4efd-a90a-b142a90bffa3"
        },
        "Threat Intelligence": {
          "name": "Threat Intelligence",
          "version": "1.0",
          "description": "Leverages external threat intelligence feeds and indicators to identify known \nmalicious activity, including IOCs, TTPs, and threat actor behaviors.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "fb643a20-e3b4-4ed5-a017-87bd6e884bc9"
        },
        "Frequency Analysis": {
          "name": "Frequency Analysis",
          "version": "1.0",
          "description": "Monitors the frequency of specific events or patterns over time to identify \nunusual spikes or changes that may indicate malicious activity, such as \nbrute force attempts or data exfiltration.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "bb978737-10f4-4873-9c44-140452d003b0"
        }
      }
    },
    "detection.types": {
      "metadata": {
        "name": "Detection Types",
        "field": "detection.types",
        "description": "Purpose of different Detection Objectives",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": []
      },
      "entries": {
        "Threat": {
          "name": "Threat",
          "version": "1.0",
          "description": "Alerts meant for detection cybersecurity threats, and which should \neventually trigger Incident Response  \n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "d86e629b-df0f-45ae-b851-3fa21e0cd9c1"
        },
        "Compliance": {
          "name": "Compliance",
          "version": "1.0",
          "description": "Alerts/Alarms which are relevant from a Business Operation compliance standpoint, for example to monitor that processes are respected",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "0be140ac-c651-4d8f-9282-09eba94b52a1"
        },
        "Utility": {
          "name": "Utility",
          "version": "1.0",
          "description": "Searches and other mechanisms meant to support different processes\nnot directly related to threat detection, for example to move data\nfrom one source to another or detect log source anomalies.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "fcbcf010-a9e4-4714-b22d-a745e6c35896"
        },
        "Supportive": {
          "name": "Supportive",
          "version": "1.0",
          "description": "Objective not directly related to threat detection capabilities, but\nwhich may support another objective.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "5c8b9be3-ef99-4e75-ba7a-706f43bdfb05"
        }
      }
    },
    "efforts": {
      "metadata": {
        "name": "NIST 800-61 Recoverability Efforts",
        "field": "efforts",
        "description": "NIST Special Publication reference for recoverability effort categories that reflect the level of and type of resources required to recover from the incident.",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": [],
        "reference": "https://nvlpubs.nist.gov/nistpubs/SpecialPublications/NIST.SP.800-61r2.pdf"
      },
      "entries": {
        "Regular": {
          "name": "Regular",
          "version": "1.0",
          "description": "Time to recovery is predictable with existing resources",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Supplemented": {
          "name": "Supplemented",
          "version": "1.0",
          "description": "Time to recovery is predictable with additional resources",
