        "key": "name",
        "model": false,
        "stages": []
      },
      "entries": {
        "Available": {
          "name": "Available",
          "version": "1.0",
          "description": "Detections are easy to build, since data is available and building blocks already exist",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Minor Work": {
          "name": "Minor Work",
          "version": "1.0",
          "description": "Building the detection requires some light known and defined development",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Possible": {
          "name": "Possible",
          "version": "1.0",
          "description": "Technical details are known, but some moderate research is required to understand how to build detections",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Challenging": {
          "name": "Challenging",
          "version": "1.0",
          "description": "Available information exist to support development, but unfamiliarity will lead to a sharper learning curve",
