          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Asset and fraud": {
          "name": "Asset and fraud",
          "version": "1.0",
          "description": "Asset and fraud-related losses",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
