    "sectors": {
      "metadata": {
        "name": "Victim Industry Sector",
        "field": "sectors",
        "description": "Industry sector is an open vocabulary that describes industrial and commercial sectors. It is intended to be holistic; it has been derived from several other lists and is not limited to \"critical infrastructure\" sectors.",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": [],
        "stix": "industry-sector-ov",
        "reference": "https://docs.oasis-open.org/cti/stix/v2.1/os/stix-v2.1-os.html#_oogrswk3onck"
      },
      "entries": {
        "Opportunitistic": {
          "name": "Opportunitistic",
          "version": "1.0",
          "description": "The attacker is not particularly focusing on a particular sector, and intel shows very varied targets which are not well defined.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Agriculture": {
          "name": "Agriculture",
          "version": "1.0",
          "description": "The Agriculture sectors comprise establishments primarily engaged in growing crops, raising animals, and harvesting fish and other animals from a farm, ranch, or their natural habitats.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "agriculture",
          "misp": "stix-ttp:victim-targeting=\"food-sector\""
        },
        "Aerospace": {
          "name": "Aerospace",
          "version": "1.0",
          "description": "The aerospace industry is engaged in the research, development, and manufacture of flight vehicles, including unpowered gliders and sailplanes (see gliding), uncrewed aerial vehicles (UAVs), lighter-than-air craft (see balloon; airship), heavier-than-air craft (both fixed-wing and rotary-wing; see airplane; military aircraft), missiles (see rocket and missile system), space launch vehicles, and spacecraft (crewed and uncrewed).",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "aerospace",
          "misp": "stix-ttp:victim-targeting=\"aerospace-defence-sector\""
        },
        "Automotive": {
          "name": "Automotive",
          "version": "1.0",
          "description": "The automotive industry’s principal products are passenger automobiles and light trucks, including pickups, vans, and sport utility vehicles. Commercial vehicles (i.e., delivery trucks and large transport trucks, often called semis), though important to the industry, are secondary.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "automotive",
          "misp": "stix-ttp:victim-targeting=\"other-sector\""
        },
        "Chemical": {
          "name": "Chemical",
          "version": "1.0",
          "description": "Complex of processes, operations, and organizations engaged in the manufacture of chemicals and their derivatives.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "chemical",
          "misp": "stix-ttp:victim-targeting=\"other-sector\""
        },
        "Commercial Facilities": {
          "name": "Commercial Facilities",
          "version": "1.0",
          "description": "The Commercial Facilities Sector includes a diverse range of sites that draw large crowds of people for shopping, business, entertainment, or lodging.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "commercial",
          "misp": "stix-ttp:victim-targeting=\"other-sector\""
        },
        "Medias & Public Communications": {
          "name": "Medias & Public Communications",
          "version": "1.0",
          "description": "The media industry encompasses all businesses that allow information to be shared. The way that this information is shared varies massively, with some examples of media including radio, television, newspapers, social media, video games, film and music.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "communications",
          "misp": "stix-ttp:victim-targeting=\"media-entertainment-sector\""
        },
        "Construction": {
          "name": "Construction",
          "version": "1.0",
          "description": "The branch of manufacture and trade based on the building, maintaining, and repairing structures. This includes drilling and solid mineral exploration.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "construction",
          "misp": "stix-ttp:victim-targeting=\"construction-engineering-sector\""
        },
        "Defense": {
          "name": "Defense",
          "version": "1.0",
          "description": "Public organization and private firms involved in research, development, production, and service of military materiel, equipment and facilities.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "defense",
          "misp": "stix-ttp:victim-targeting=\"aerospace-defence-sector\""
        },
        "Education": {
          "name": "Education",
          "version": "1.0",
          "description": "The education sector or education system is a group of institutions (ministries of education, local educational authorities, teacher training institutions, schools, universities, etc.) whose primary purpose is to provide education in educational settings.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "education",
          "misp": "stix-ttp:victim-targeting=\"other-sector\""
        },
        "Energy": {
          "name": "Energy",
          "version": "1.0",
          "description": "The energy industry is the totality of all of the industries involved in the production and sale of energy, including fuel extraction, manufacturing, refining and distribution.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "energy",
          "misp": "stix-ttp:victim-targeting=\"energy-sector\""
        },
        "Entertainment": {
          "name": "Entertainment",
          "version": "1.0",
          "description": "Entertainment Industry means an employer including but not limited to any organization, or individual using the services of any minor in: motion pictures of any type, using any format including theatrical film, commercial, documentary, and television program, or similar format by any medium including but not limited to photography; recording; modeling; theatrical productions; publicity; and any performances where minors perform or entertain.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "entertainment",
          "misp": "stix-ttp:victim-targeting=\"media-entertainment-sector\""
        },
        "Financial Services": {
          "name": "Financial Services",
          "version": "1.0",
          "description": "The financial services sector provides financial services to people and corporations. This segment of the economy is made up of a variety of financial firms including banks, investment houses, lenders, finance companies, real estate brokers, and insurance companies.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "financial-services",
          "misp": "stix-ttp:victim-targeting=\"financial-sector\""
        },
        "Government Facilities": {
          "name": "Government Facilities",
          "version": "1.0",
          "description": "The Government Facilities Sector includes a wide variety of buildings, located in the United States and overseas, that are owned or leased by federal, state, local, and tribal governments.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "government",
          "misp": "stix-ttp:victim-targeting=\"government-international-organizations-sector\""
        },
        "Emergency Services": {
          "name": "Emergency Services",
          "version": "1.0",
          "description": "The Emergency Services Sector (ESS) is a community of millions of highly-skilled, trained personnel, along with the physical and cyber resources, that provide a wide range of prevention, preparedness, response, and recovery services during both day-to-day operations and incident response.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "emergency-services",
          "misp": "stix-ttp:victim-targeting=\"government-international-organizations-sector\""
        },
        "Local Government": {
          "name": "Local Government",
          "version": "1.0",
          "description": "The smallest or second largest geographical area into which the country as a whole may be divided for political or administrative purposes, such as a municipality or district. A local government often has the fiscal authority to raise taxes within its territory and should have the ability to spend at least some of its income according to its own policies, and appoint or elect its own officers.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "government-local",
          "misp": "stix-ttp:victim-targeting=\"government-international-organizations-sector\""
        },
        "National Government": {
          "name": "National Government",
          "version": "1.0",
          "description": "A central government is the government that is a controlling power over a unitary state.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "government-national",
          "misp": "stix-ttp:victim-targeting=\"government-international-organizations-sector\""
        },
        "Public Government Services": {
          "name": "Public Government Services",
          "version": "1.0",
          "description": "A public service is something such as health care, transport, or the removal of waste which is organized by the government or an official body in order to benefit all the people in a particular society or community.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "government-public-services",
          "misp": "stix-ttp:victim-targeting=\"government-international-organizations-sector\""
        },
        "Regional Government": {
          "name": "Regional Government",
          "version": "1.0",
          "description": "The largest geographical area into which the country as a whole may be divided for political or administrative purposes, such as a state, province, department or region. A regional government usually has the fiscal authority to raise taxes within its territory and should have the ability to spend at least some of its income according to its own policies, and appoint or elect its own officers.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "government-regional",
          "misp": "stix-ttp:victim-targeting=\"government-international-organizations-sector\""
        },
        "Healthcare": {
          "name": "Healthcare",
          "version": "1.0",
          "description": "The Healthcare and Public Health Sector protects all sectors of the economy from hazards such as terrorism, infectious disease outbreaks, and natural disasters.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "healthcare",
          "misp": "stix-ttp:victim-targeting=\"healthcare-sector\""
        },
        "Hospitality & Leisure": {
          "name": "Hospitality & Leisure",
          "version": "1.0",
          "description": "The leisure and hospitality industry sector includes a broad category of fields within the service industry such as lodging, food services, event planning, theme parks, transportation and other tourism oriented products and services.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "hospitality-leisure",
          "misp": "stix-ttp:victim-targeting=\"other-sector\""
        },
        "Infrastructure": {
          "name": "Infrastructure",
          "version": "1.0",
          "description": "Infrastructure is the set of fundamental facilities and systems that support the sustainable functionality of households and firms.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "infrastructure",
          "misp": "stix-ttp:victim-targeting=\"other-sector\""
        },
        "Dams": {
          "name": "Dams",
          "version": "1.0",
          "description": "The Dams Sector delivers critical water retention and control services in the United States, including hydroelectric power generation, municipal and industrial water supplies, agricultural irrigation, sediment and flood control, river navigation for inland bulk shipping, industrial waste management, and recreation.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "dams",
          "misp": "stix-ttp:victim-targeting=\"other-sector\""
        },
        "Nuclear": {
          "name": "Nuclear",
          "version": "1.0",
          "description": "Nuclear power is the use of nuclear reactions to produce electricity. Nuclear power can be obtained from nuclear fission, nuclear decay and nuclear fusion reactions.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "nuclear",
          "misp": "stix-ttp:victim-targeting=\"energy-sector\""
        },
        "Water": {
          "name": "Water",
          "version": "1.0",
          "description": "The water industry provides drinking water and wastewater services (including sewage treatment) to residential, commercial, and industrial sectors of the economy.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "water",
          "misp": "stix-ttp:victim-targeting=\"natural-resources-sector\""
        },
        "Insurance": {
          "name": "Insurance",
          "version": "1.0",
          "description": "The insurance sector is made up of companies that offer risk management in the form of insurance contracts. The basic concept of insurance is that one party, the insurer, will guarantee payment for an uncertain future event.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "insurance",
          "misp": "stix-ttp:victim-targeting=\"financial-sector\""
        },
        "Manufacturing": {
          "name": "Manufacturing",
          "version": "1.0",
          "description": "Manufacturing industries are those that engage in the transformation of goods, materials or substances into new products. The transformational process can be physical, chemical or mechanical.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "manufacturing",
          "misp": "stix-ttp:victim-targeting=\"construction-engineering-sector\""
        },
        "Mining": {
          "name": "Mining",
          "version": "1.0",
          "description": "Mining industry indicates the cluster of process that are involved with extraction, management, and processing of naturally occurring solid minerals from the earth surface. As a product of mining, various economically valuable products might be obtained, that is, coal, diamond, metallic ores, oil, and so on.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "mining",
          "misp": "stix-ttp:victim-targeting=\"natural-resources-sector\""
        },
        "Non-Profit Organization": {
          "name": "Non-Profit Organization",
          "version": "1.0",
          "description": "A nonprofit organization (NPO), also known as a non-business entity, not-for-profit organization, or nonprofit institution, is a legal entity organized and operated for a collective, public or social benefit, in contrast with an entity that operates as a business aiming to generate a profit for its owners.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "non-profit"
        },
        "Pharmaceuticals": {
          "name": "Pharmaceuticals",
          "version": "1.0",
          "description": "The pharmaceutical industry discovers, develops, produces, and markets drugs or pharmaceutical drugs for use as medications to be administered to patients (or self-administered), with the aim to cure them, vaccinate them, or alleviate symptoms.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "pharmaceuticals",
          "misp": "stix-ttp:victim-targeting=\"other-sector\""
        },
        "Retail": {
          "name": "Retail",
          "version": "1.0",
          "description": "Retail is the sale of goods and services to consumers, in contrast to wholesaling, which is sale to business or institutional customers.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "retail",
          "misp": "stix-ttp:victim-targeting=\"retail-sector\""
        },
        "High tech": {
          "name": "High tech",
          "version": "1.0",
          "description": "High technology (high tech), also known as frontier technology (frontier tech), is technology that is at the cutting edge, the most advanced technology available.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "technology",
          "misp": "stix-ttp:victim-targeting=\"hightech-it-sector\""
        },
        "Telecommunications": {
          "name": "Telecommunications",
          "version": "1.0",
          "description": "The telecommunications industry is made up of cable companies, internet service providers, satellite companies, and telephone companies. Telecommunications is defined as communicating over a distance.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "telecommunications"
        },
        "Transportation": {
          "name": "Transportation",
          "version": "1.0",
          "description": "The transportation sector is an important industry sector in the economy that deals with the movement of people and products. These include companies such as airlines, trucking, railroads, shipping, and logistics firms, as well as those that provide transportation infrastructure.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "transportation",
          "misp": "stix-ttp:victim-targeting=\"transportation-sector\""
        },
        "Public Utilities": {
          "name": "Public Utilities",
          "version": "1.0",
          "description": "Enterprise that provides certain classes of services to the public, including common carrier transportation (buses, airlines, railroads, motor freight carriers, pipelines, etc.); telephone and telegraph; power, heat, and light; and community facilities for water, sanitation, and similar services.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "utilities"
        },
        "Professional Services": {
          "name": "Professional Services",
          "version": "1.0",
          "description": "Professional services are occupations in the service sector requiring special training in the arts or sciences. Some professional services, such as architects, accountants, engineers, doctors, lawyers, and teachers, require the practitioner to hold professional degrees or licenses and possess specific skills. Other professional services involve providing specialist business support to businesses of all sizes and in all sectors; this can include tax advice, supporting a company with accounting, IT services or providing management advice.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "misp": "stix-ttp:victim-targeting=\"business-professional-sector\""
        }
      }
    },
    "severity": {
      "metadata": {
        "name": "Threat Severity",
        "field": "severity",
        "description": "The severity summarizes the overall danger of incident the vector will provoke, and is to be derived (WIP) from impact, leverage, and difficulty to execute.",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": [],
        "reference": "https://www.ncsc.gov.uk/news/new-cyber-attack-categorisation-system-improve-uk-response-incidents"
      },
      "entries": {
        "Localised incident": {
          "name": "Localised incident",
          "version": "1.0",
          "description": "A cyber attack on an individual, or preliminary indications of cyber activity against a small or medium-sized organisation.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Moderate incident": {
          "name": "Moderate incident",
          "version": "1.0",
          "description": "A cyber attack on a small organisation, or which poses a considerable risk to a medium-sized organisation, or preliminary indications of cyber activity against a large organisation or the government.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Substantial incident": {
          "name": "Substantial incident",
          "version": "1.0",
          "description": "A cyber attack which has a serious impact on a medium-sized organisation, or which poses a considerable risk to a large organisation or wider / local government.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Significant incident": {
          "name": "Significant incident",
          "version": "1.0",
          "description": "A cyber attack which has a serious impact on a large organisation or on wider / local government, or which poses a considerable risk to central government or (inter)national essential services.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Highly significant incident": {
          "name": "Highly significant incident",
          "version": "1.0",
          "description": "A cyber attack which has a serious impact on central government, (inter)national essential services, a large proportion of the (inter)national population, or the (inter)national economy.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "National cyber emergency": {
          "name": "National cyber emergency",
          "version": "1.0",
          "description": "A cyber attack which causes sustained disruption of (inter)national essential services or affects (inter)national national security, leading to severe economic or social consequences or to loss of life.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        }
      }
    },
    "signal.entities": {
      "metadata": {
        "name": "Signal Entities",
        "field": "signal.entities",
        "description": "Core objects or attributes that a detection signal focuses on.\nStages group keys, and an authored value is ALWAYS prefixed with its stage id (for example Host::Process, or Network::IP Address). The prefix is what tells two stages' identically-named keys apart: Account, User, Email, Token, Authentication, Permissions and API Call are each defined under two stages. These entities align with common detection methodologies and frameworks such as MITRE ATT&CK.\n",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": [
          {
            "id": "Host",
            "name": "Host Entities",
            "description": "Host Related Entities"
          },
          {
            "id": "Network",
            "name": "Network Entities",
            "description": "Network Related Entities"
          },
          {
            "id": "Cloud",
            "name": "Cloud Entities",
            "description": "Cloud Related Entities"
          }
        ]
      },
      "entries": {
        "Account": {
          "name": "Account",
          "version": "1.0",
          "description": "Represents a user account entity, including local, domain, or cloud-based\naccounts.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host",
            "Cloud"
          ],
          "id": "39d5e5fa-d7d8-4617-9eb0-a31e61b78d49"
        },
        "User": {
          "name": "User",
          "version": "1.0",
          "description": "Represents an individual user, including their identity and associated\nattributes.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host",
            "Cloud"
          ],
          "id": "44156a4d-2b7b-4835-b6c3-9f329b81dbd0"
        },
        "Hostname": {
          "name": "Hostname",
          "version": "1.0",
          "description": "Represents the name of a host or device in the network.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "c7bad96d-6e37-4d8d-8373-ce5489958068"
        },
        "IP Address": {
          "name": "IP Address",
          "version": "1.0",
          "description": "Represents an IPv4 or IPv6 address associated with a host or network\nconnection.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Network"
          ],
          "id": "f25eef26-c9df-44ae-9ae2-030943600f93"
        },
        "Process": {
          "name": "Process",
          "version": "1.0",
          "description": "Represents a running process on a host, including its attributes like\nprocess ID and command line.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "f73506f3-fdf9-473c-8286-ad16ae56ddf6"
        },
        "Command Line": {
          "name": "Command Line",
          "version": "1.0",
          "description": "Represents the command line arguments used to execute a process.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "aca091fd-d169-49b3-8d92-3c11616b66db"
        },
        "File": {
          "name": "File",
          "version": "1.0",
          "description": "Represents a file on a system, including its name, path, and attributes.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "8ba0fe1b-74fc-4417-87b0-788bc7e1b227"
        },
        "File Hash": {
          "name": "File Hash",
          "version": "1.0",
          "description": "Represents the hash of a file, used to uniquely identify its contents.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "c23fbfd5-0dd5-4dca-bc63-5e08a7a83c22"
        },
        "Registry Key/Value": {
          "name": "Registry Key/Value",
          "version": "1.0",
          "description": "Represents a Windows registry key, including its path and associated\nvalues.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "cb7e78f2-c4cd-43fb-b3ab-cb0d22c55424"
        },
        "Domain": {
          "name": "Domain",
          "version": "1.0",
          "description": "Represents a domain name, including those used in network communications\nor as part of URLs.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "e6940ca8-54b5-4f4e-8b41-4412547c09aa"
        },
        "URL": {
          "name": "URL",
          "version": "1.0",
          "description": "Represents a Uniform Resource Locator (URL), often used in web-based\nattacks or phishing campaigns.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Network"
          ],
          "id": "7d112622-4a2c-434a-b80a-f3998dfb090b"
        },
        "Resource": {
          "name": "Resource",
          "version": "1.0",
          "description": "Represents a cloud-based resource, such as virtual machines, storage buckets, \nor serverless functions. These resources are often targeted in cloud \nenvironments for unauthorized access or exploitation.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Cloud"
          ],
          "id": "46673041-bbbb-4fd1-87fc-d89ac4c4546f"
        },
        "Email": {
          "name": "Email",
          "version": "1.0",
          "description": "Represents an email entity, including sender, recipient, subject, and \nmessage content. Emails are often used in phishing attacks or as a \nvector for delivering malicious payloads.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Network",
            "Host"
          ],
          "id": "d187990e-cebb-41cd-94d3-828beb75bdde"
        },
        "Geolocation": {
          "name": "Geolocation",
          "version": "1.0",
          "description": "Represents the geographic location of an IP address or device. Geolocation \ndata is often used to detect anomalies, such as logins from unexpected regions.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "1e3976f7-ece0-4601-ba6b-be805aa27f84"
        },
        "Protocol": {
          "name": "Protocol",
          "version": "1.0",
          "description": "Represents a network protocol, such as HTTP, HTTPS, FTP, or SMB. Protocols \nare often analyzed to identify unusual or malicious activity.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Network"
          ],
          "id": "0d80566c-88a9-4815-85d9-871ded46b88c"
        },
        "Network Connection": {
          "name": "Network Connection",
          "version": "1.0",
          "description": "Represents a network connection, including source and destination IPs, ports, \nand protocols. This entity is critical for detecting suspicious or unauthorized \ncommunication between systems.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Network"
          ],
          "id": "7e868645-b4f7-4901-8701-023f05c24799"
        },
        "Port": {
          "name": "Port",
          "version": "1.0",
          "description": "Represents a network port, including source and destination ports. Ports \nare often used to detect unauthorized services or unusual traffic patterns.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Network"
          ],
          "id": "c7598e49-6c2e-459e-a354-8c326752097c"
        },
        "Device Type": {
          "name": "Device Type",
          "version": "1.0",
          "description": "Represents the type of device, such as a workstation, server, mobile device, \nor IoT device. This entity helps in identifying and categorizing assets.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "d9dd557d-7438-4e4f-8e10-f021c1da2a16"
        },
        "Session": {
          "name": "Session",
          "version": "1.0",
          "description": "Represents a user or system session, including session IDs and associated \nactivities. Sessions are often analyzed to detect unauthorized access or \nunusual behavior.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Network"
          ],
          "id": "7da2b6bf-62ac-4e9e-ab5f-187b5b1407e0"
        },
        "Certificate": {
          "name": "Certificate",
          "version": "1.0",
          "description": "Represents a digital certificate, including its issuer, validity, and usage. \nCertificates are often analyzed to detect spoofing or expired credentials.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Network"
          ],
          "id": "ca44ed3e-d363-4089-a155-50c716b8400f"
        },
        "Token": {
          "name": "Token",
          "version": "1.0",
          "description": "Represents an authentication or access token, such as OAuth tokens or API keys. \nTokens are often analyzed to detect unauthorized access or misuse.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host",
            "Cloud"
          ],
          "id": "ff069dd1-cfd0-494c-908f-3c295c5dd33f"
        },
        "Software": {
          "name": "Software",
          "version": "1.0",
          "description": "Represents a software package, including its name, version, and installation \nsource. Software packages are often analyzed to detect unauthorized or \nvulnerable software.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "6ac71d2e-f8f0-4353-8a29-d1e0c2875acb"
        },
        "DNS Query": {
          "name": "DNS Query",
          "version": "1.0",
          "description": "Represents a DNS query, including the requested domain and response. DNS \nqueries are often analyzed to detect malicious domains or command-and-control \n(C2) activity.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Network"
          ],
          "id": "c2ed0ba9-1ff0-403e-914e-b72a5224b234"
        },
        "Authentication": {
          "name": "Authentication",
          "version": "1.0",
          "description": "Represents an authentication attempt, including the user, source IP, and \nsuccess or failure status. Authentication events are critical for detecting \nbrute force attacks or unauthorized access.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host",
            "Cloud"
          ],
          "id": "004ab636-1a3a-43e1-bab0-ed171f8df417"
        },
        "Service": {
          "name": "Service",
          "version": "1.0",
          "description": "Represents a system service, including its name, status, and associated \nprocesses. Services are often analyzed to detect unauthorized or malicious \nservices running on a host.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "3a13580e-2959-4729-afea-07f6fac6ba71"
        },
        "Scheduled Task": {
          "name": "Scheduled Task",
          "version": "1.0",
          "description": "Represents a scheduled task or cron job, including its configuration and \nexecution details. Scheduled tasks are often used by attackers for persistence.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Host"
          ],
          "id": "7860dfeb-7baf-4bee-b8a2-ef6fa76892aa"
        },
        "API Call": {
          "name": "API Call",
          "version": "1.0",
          "description": "Represents an API call, including its endpoint, parameters, and response. \nAPI calls are often analyzed to detect unauthorized access or data exfiltration.\n",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
            "Network",
            "Cloud"
          ],
          "id": "20ab1a7b-ccba-408a-ae2f-37c130a21a24"
        },
        "Permissions": {
          "name": "Permissions",
          "version": "1.0",
          "description": "Leverages a set of allowed actions",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [
