    "tier": {
      "metadata": {
        "name": "Threat Actor Tier",
        "field": "tier",
        "description": "Category within which the threat actor is best summarized, and which gives an indicator of the adversarial mindset motivated by strategic objectives.",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": [],
        "stix": "threat-actor-type-ov",
        "reference": "https://docs.oasis-open.org/cti/stix/v2.1/os/stix-v2.1-os.html#_tqbl8z36yoir"
      },
      "entries": {
        "Ideological Activists": {
          "name": "Ideological Activists",
          "version": "1.0",
          "description": "Highly motivated, potentially destructive supporter of a social or political cause (e.g., trade, labor, environment, etc.) that attempts to disrupt an organization's business model or damage their image.\n\nThis category includes actors sometimes referred to as anarchists, cyber vandals, extremists, and hacktivists.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "activist"
        },
        "Commercial Competitor": {
          "name": "Commercial Competitor",
          "version": "1.0",
          "description": "An organization that competes in the same economic marketplace.\n\nThe goal of a competitor is to gain an advantage in business with respect to the rival organization it targets. It usually does this by copying intellectual property, trade secrets, acquisition strategies, or other technical or business data from a rival organization with the intention of using the data to bolster its own assets and market position.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "competitor"
        },
        "Organized Cyber Criminals": {
          "name": "Organized Cyber Criminals",
          "version": "1.0",
          "description": "An enterprise organized to conduct significant, large-scale criminal activity for profit.\n\nCrime syndicates, also known as organized crime, are generally large, well-resourced groups that operate to create profit from all types of crime.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "crime-syndicate"
        },
        "Black Hat": {
          "name": "Black Hat",
          "version": "1.0",
          "description": "Individual who commits computer crimes, often for personal financial gain and often involves the theft of something valuable.\n\nIntellectual property theft, extortion via ransomware, and physical destruction are common examples. A criminal as defined here refers to those acting individually or in very small or informal groups. For sophisticated organized criminal activity, see the crime syndicate descriptor.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "criminal"
        },
        "Nation State": {
          "name": "Nation State",
          "version": "1.0",
          "description": "Entities who work for the government or military of a nation state or who work at their direction.\n\nThese actors typically have access to significant support, resources, training, and tools and are capable of designing and executing very sophisticated and effective Intrusion Sets and Campaigns.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "nation-state"
        },
        "Sensationalists": {
          "name": "Sensationalists",
          "version": "1.0",
          "description": "Seeks to cause embarrassment and brand damage by exposing sensitive information in a manner designed to cause a public relations crisis.\n\nA sensationalist may be an individual or small group of people motivated primarily by a need for notoriety. Unlike the activist, the sensationalist generally has no political goal, and is not using bad PR to influence the target to change its behavior or business practices.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "sensationalist"
        },
        "Cyber Terrorists": {
          "name": "Cyber Terrorists",
          "version": "1.0",
          "description": "Uses extreme violence to advance a social or political agenda as well as monetary crimes to support its activities.\n\nIn this context a terrorist refers to individuals who target noncombatants with violence to send a message of fear far beyond the actual events. They may act independently or as part of a terrorist organization.\n\nTerrorist organizations must typically raise much of their operating budget through criminal activity, which often occurs online. Terrorists are also often adept at using and covertly manipulating social media for both recruitment and impact.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "stix": "terrorist"
        }
      }
    },
    "tlp": {
      "metadata": {
        "name": "Traffic Light Protocol",
        "field": "tlp",
        "description": "The Traffic Light Protocol - or short: TLP - was designed with the objective to create a favorable classification scheme for sharing sensitive information while keeping the control over its distribution at the same time.",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": [],
        "reference": "https://www.first.org/tlp/"
      },
      "entries": {
        "clear": {
          "name": "clear",
          "version": "1.0",
          "description": "Recipients can spread this to the world, there is no limit on disclosure.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "TLP:CLEAR",
          "misp": "tlp:clear"
        },
        "green": {
          "name": "green",
          "version": "1.0",
          "description": "Limited disclosure, recipients can spread this within their community. Sources may use TLP:GREEN when information is useful to increase awareness within their wider community.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "TLP:GREEN",
          "misp": "tlp:green"
        },
        "amber": {
          "name": "amber",
          "version": "1.0",
          "description": "Limited disclosure, recipients can only spread this on a need-to-know basis within their organization and its clients.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "TLP:AMBER",
          "misp": "tlp:amber"
        },
        "amber+strict": {
          "name": "amber+strict",
          "version": "1.0",
          "description": "Similar to TLP:AMBER, but restricts sharing to the organization only.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "TLP:AMBER+STRICT",
          "misp": "tlp:amber+strict"
        },
        "red": {
          "name": "red",
          "version": "1.0",
          "description": "For the eyes and ears of individual recipients only, no further disclosure.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "id": "TLP:RED",
          "misp": "tlp:red"
        }
      }
    },
    "viability": {
      "metadata": {
        "name": "Vector Viability",
        "field": "viability",
        "description": "Described with estimative language (likelyhood probability), describes how likely the analyst believes the vector to actually be realized on the organization infrastructure. Estimative language describes quality and credibility of underlying sources, data, and methodologies based Intelligence Community Directive 203 (ICD 203) and JP 2-0, Joint Intelligence.",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": [],
        "reference": "https://www.dni.gov/files/documents/ICD/ICD%20203%20Analytic%20Standards.pdf"
      },
      "entries": {
        "Environment dependent": {
          "name": "Environment dependent",
          "version": "1.0",
          "description": "Depends",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Almost no chance": {
          "name": "Almost no chance",
          "version": "1.0",
          "description": "Remote - 01-05%",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "misp": "estimative-language:likelihood-probability=\"almost-no-chance\""
        },
        "Very Unlikely": {
          "name": "Very Unlikely",
          "version": "1.0",
          "description": "Highly improbable - 05-20%",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "misp": "estimative-language:likelihood-probability=\"very-unlikely\""
        },
        "Unlikely": {
          "name": "Unlikely",
          "version": "1.0",
          "description": "Improbable (improbably) - 20-45%",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "misp": "estimative-language:likelihood-probability=\"unlikely\""
        },
        "Roughly even chance": {
          "name": "Roughly even chance",
          "version": "1.0",
          "description": "Roughly even odds - 45-55%",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "misp": "estimative-language:likelihood-probability=\"roughly-even-chance\""
        },
        "Likely": {
          "name": "Likely",
          "version": "1.0",
          "description": "Probable (probably) - 55-80%",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "misp": "estimative-language:likelihood-probability=\"likely\""
        },
        "Very Likely": {
          "name": "Very Likely",
          "version": "1.0",
          "description": "Highly probable - 80-95%",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "misp": "estimative-language:likelihood-probability=\"very-likely\""
        },
        "Almost certain": {
          "name": "Almost certain",
          "version": "1.0",
          "description": "Nearly certain - 95-99%",
          "icon": "",
          "link": "",
          "tide.vocab.stages": [],
          "misp": "estimative-language:likelihood-probability=\"almost-certain\""
        }
      }
    },
    "violation": {
      "metadata": {
        "name": "Policy, mandate or governance violations",
        "field": "violation",
        "description": "Categories of usage violations which is not directly the result of an exercised threat, but needs to be monitored and accounted for illegitimate behaviours.",
        "icon": "",
        "key": "name",
        "model": false,
        "stages": []
      },
      "entries": {
        "Illegal content streaming or usage of disallowed web service": {
          "name": "Illegal content streaming or usage of disallowed web service",
          "version": "1.0",
          "description": "This could be copyrighted material, but also includes other illegal categories",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Insecure communication protocol": {
          "name": "Insecure communication protocol",
          "version": "1.0",
          "description": "Usage of protocols that are outdated and unsecure. Examples of such protocols are FTP and telnet",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Vulnerable system or service": {
          "name": "Vulnerable system or service",
          "version": "1.0",
          "description": "Any vulnerable systems or applications / services that leave the system vulnerable for compromise",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Unauthorized process launched": {
          "name": "Unauthorized process launched",
          "version": "1.0",
          "description": "Launch of an unauthorized process. Examples of such processes are psexec, powershell and the command prompt. Also covers unauthorized processes running as a service",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Illegal or aberrant application found on host": {
          "name": "Illegal or aberrant application found on host",
          "version": "1.0",
          "description": "Any application present on hosts that are not allowed by policy or are quite simply illegal. Examples of such applications are hacking tools and pirated software",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Resource abuse": {
          "name": "Resource abuse",
          "version": "1.0",
          "description": "This use case is reserved for situations where systems are being abused, for example for bitcoin mining",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Unauthorized use of high-privileged account": {
          "name": "Unauthorized use of high-privileged account",
          "version": "1.0",
          "description": "Any unauthorized use of accounts with high privileges, such as root accounts on Linux / UNIX and administrator accounts on Windows",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Unauthorized modification of technical policy": {
          "name": "Unauthorized modification of technical policy",
          "version": "1.0",
          "description": "Unauthorized modification of configuration settings. This can be a compliance issue, where the configuration may result in a hardening baseline deviation. It can also be part of malicious activity",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        },
        "Uncompliant remote access to internal resources": {
          "name": "Uncompliant remote access to internal resources",
          "version": "1.0",
          "description": "Legitimate remote activities not being achieved with organization approved means, such as using a third-party VPN or service, unsupported protocols or non-standard infrastructure.",
          "icon": "",
          "link": "",
          "tide.vocab.stages": []
        }
      }
    },
